\subsection{Proof of \Cref{thm:power}}

Fix $p > 0$ and $s\in (0,1)$, and let $g(s,p) := \frac{1}{1 + \frac{(s(1+p))^{1+p}}{p^p}}$.

    First, we show that $\FVRMath(R_{p\text{-power}},s) \le g(s,p)$.   
    Take an arbitrary instance, and let $a^*$ be the candidate chosen by $R_{p\text{-power}}$.
    Let $B := \set{i \in N \mid |A_i| \ge sm \text{ and } a^* \notin A_i}$ be the set of $s$-flexible voters who disapprove $a^*$, and let $r := |B|/n$.
    It is sufficient to show that $r \le g(s,p)$.

    Since $N_{a^*} \subseteq N \setminus B$, it holds that $\sc_p(a^*) \le \sum_{i \in N\setminus B} f_i^p$. 
    Let us consider the average score of all candidates, $\frac{1}{m} \sum_{a \in M} \sc_p(a)$. 
    We have that
    \begin{align*}
        \frac{1}{m} \sum_{a \in M} \sc_p(a)
        &= \frac{1}{m} \sum_{a \in M} \sum_{i \in N_a} f_i^p\\
        &= \frac{1}{m^{1+p}}\sum_{a \in M} \sum_{i \in N_a} |A_i|^p\\
        &= \frac{1}{m^{1+p}}\sum_{i \in N} \sum_{a \in A_i}  |A_i|^p
        = \frac{1}{m^{1+p}}\sum_{i \in N}  |A_i|^{1+p}
        = \sum_{i \in N} f_i^{1+p}
        = \sum_{i \in B} f_i^{1+p} + \sum_{i \in N \setminus B} f_i^{1+p}.
    \end{align*}

    For each $i \in B$, it holds by definition that $f_i \ge s$, so $\sum_{i \in B} f_i^{1+p} \ge |B| \cdot s^{1+p} = rn s^{1+p}$.
    Since $a^*$ is a candidate with the maximal score, it must hold that $\sc(a^*) 
    \ge \frac{1}{m} \sum_{a \in M} \sc_p(a)$.
    Therefore,
    \begin{align*}
    \sum_{i \in N\setminus B} f_i^p
    \ge \sc(a^*) 
    \ge \frac{1}{m} \sum_{a \in M} \sc_p(a) 
    = \sum_{i \in B} f_i^{1+p} + \sum_{i \in N \setminus B} f_i^{1+p}
    \ge rns^{1+p} + \sum_{i \in N \setminus B} f_i^{1+p}.
    \end{align*}
    That is, $rns^{1+p} \le \sum_{i\in N\setminus B} f_i^p (1-f_i)$.
    Note that within the range $x\in [0,1]$, basic calculus shows that the function $x^p(1-x)$ is maximized at $x = \frac{p}{1+p}$, so we get
    \begin{align*}
    rns^{1+p} 
    \le \sum_{i\in N\setminus B} \left(\frac{p}{1+p}\right)^p\frac{1}{1+p} 
    = \sum_{i\in N\setminus B} \frac{p^p}{(1+p)^{1+p}}
    = (1-r)n \cdot \frac{p^p}{(1+p)^{1+p}}.
    \end{align*}
    Cancelling $n$ from both sides and solving for $r$, we obtain
    \begin{align*}
    r \le \frac{\frac{p^p}{(1+p)^{1+p}}}{s^{1+p} + \frac{p^p}{(1+p)^{1+p}}}
    = \frac{1}{1 + \frac{(s(1+p))^{1+p}}{p^p}} = g(s,p).
    \end{align*}
    This proves that $\FVRMath(R_{p\text{-power}},s) \le g(s,p)$.

    Next, we show that $\FVRMath(R_{p\text{-power}},s) \ge g(s,p)$.
    Take any $r < g(s,p)$.
    It suffices to show that there exists an instance where a group of at least $rn$ voters are all $s$-flexible but do not approve the candidate chosen by the $p$-power scoring rule.
    Consider an instance with sufficiently large $n$ and $m$ (to be made more precise later), and let $a^*$ be a candidate.
    Let $C$ be a group of $\ceiling{rn}$ voters, and assume that each voter in $C$ approves exactly $\ceiling{sm}$ candidates in $M\setminus\{a^*\}$, with the approvals distributed among these candidates as equally as possible.
    Further, assume that each voter in $N\setminus C$ approves $\big\lceil\frac{p}{1+p}\cdot m\big\rceil - 1$ candidates in $M\setminus\{a^*\}$, with the approvals distributed among these candidates as equally as possible; moreover, each of these voters also approves $a^*$.

    In this instance, we have    
    \begin{align*}
    \sc_p(a^*) 
    = \sum_{i \in N\setminus C} f_i^p
    = (n-\ceiling{rn})\cdot\left(\frac{\big\lceil\frac{p}{1+p}\cdot m\big\rceil}{m}\right)^p
    = \floor{(1-r)n}\cdot\left(\frac{\big\lceil\frac{p}{1+p}\cdot m\big\rceil}{m}\right)^p.
    \end{align*}
    On the other hand, each candidate besides $a^*$ is approved by at most $\left\lceil{\frac{\ceiling{rn}\cdot \ceiling{sm}}{m-1}}\right\rceil$ voters in $C$, and approved by at most $\bigg\lceil{\frac{\floor{(1-r)n}\cdot \big(\big\lceil\frac{p}{1+p}\cdot m\big\rceil-1\big)}{m-1}}\bigg\rceil$ voters in $N\setminus C$.
    Hence, the score of each such candidate $a$ is at most
    \begin{align*}
    \sc_p(a) 
    \le \left\lceil{\frac{\ceiling{rn}\cdot \ceiling{sm}}{m-1}}\right\rceil \cdot\left(\frac{\ceiling{sm}}{m}\right)^p 
    + \Bigg\lceil{\frac{\floor{(1-r)n}\cdot \big(\big\lceil\frac{p}{1+p}\cdot m\big\rceil-1\big)}{m-1}}\Bigg\rceil \cdot \left(\frac{\big\lceil\frac{p}{1+p}\cdot m\big\rceil}{m}\right)^p.
    \end{align*}
    We will show that $\sc_p(a^*) > \sc_p(a)$ when $n$ and $m$ are large enough.
    This is sufficient to complete the proof, because it implies that the rule $R_{p\text{-power}}$ selects the candidate $a^*$, which is approved by none of the voters in $C$.

    We have
    \begin{align*}
    \sc_p(a^*) - \sc_p(a) 
    &\ge \floor{(1-r)n}\cdot\left(\frac{\big\lceil\frac{p}{1+p}\cdot m\big\rceil}{m}\right)^p\\
    &\quad- \left\lceil{\frac{\ceiling{rn}\cdot \ceiling{sm}}{m-1}}\right\rceil \cdot\left(\frac{\ceiling{sm}}{m}\right)^p 
    - \Bigg\lceil{\frac{\floor{(1-r)n}\cdot \big(\big\lceil\frac{p}{1+p}\cdot m\big\rceil-1\big)}{m-1}}\Bigg\rceil \cdot \left(\frac{\big\lceil\frac{p}{1+p}\cdot m\big\rceil}{m}\right)^p.
    \end{align*}
    As $m$ grows, $\frac{\big\lceil\frac{p}{1+p}\cdot m\big\rceil}{m}$ and $\frac{\big\lceil\frac{p}{1+p}\cdot m\big\rceil-1}{m-1}$ converge to $\frac{p}{1+p}$, while $\frac{\ceiling{sm}}{m}$ and $\frac{\ceiling{sm}}{m-1}$ converge to $s$.
    In this case, the right-hand side of the inequality above becomes
    \begin{align*}
    \floor{(1-r)n}\cdot\left(\frac{p}{1+p}\right)^p  
    - \ceiling{\ceiling{rn}s}\cdot s^p 
    - \left\lceil\floor{(1-r)n}\cdot \frac{p}{1+p}\right\rceil \cdot \left(\frac{p}{1+p}\right)^p.
    \end{align*}
    It suffices to show that this expression is positive when $n$ is large enough.
    Note that the expression is at least
    \begin{align*}
    &((1-r)n - 1)\cdot\left(\frac{p}{1+p}\right)^p 
    - (((rn+1)s)+1)\cdot s^p
    - \left((1-r)n\cdot \frac{p}{1+p} + 1\right) \cdot \left(\frac{p}{1+p}\right)^p \\
    &= n\left[(1-r)\left(\frac{p}{1+p}\right)^p - rs^{1+p} - (1-r)\left(\frac{p}{1+p}\right)^{p+1}\right]
    - \left(\frac{p}{1+p}\right)^p - (s+1)s^p - \left(\frac{p}{1+p}\right)^p\\
    &= n\left[(1-r)\cdot\frac{p^p}{(1+p)^{1+p}}-rs^{1+p}\right]
    - 2\left(\frac{p}{1+p}\right)^p - (s+1)s^p.    
    \end{align*}
    It remains to show that the expression inside the brackets (attached to $n$) is positive.
    This expression is positive if and only if $r\left(\frac{p^p}{(1+p)^{1+p}} + s^{1+p}\right) < \frac{p^p}{(1+p)^{1+p}}$.
    The inequality holds exactly when 
    \begin{align*}
    r < \frac{\frac{p^p}{(1+p)^{1+p}}}{\frac{p^p}{(1+p)^{1+p}} + s^{1+p}}
    = \frac{1}{1 + \frac{(s(1+p))^{1+p}}{p^p}} = g(s,p),
    \end{align*}
    which is true by assumption.
    This completes the proof. \qed

\subsection{Missing Portion of Proof of \Cref{thm:general-weight}}\label{app:general-weight}

We now bound $\FVR(R^w, s)$ from below. 
For $f, f' \in \mathbb{Q}\cap (0, 1)$ such that $w(f) > 0$, let
\[
g(f, f') := \frac{(1 - f) \cdot w(f)}{(1 - f) \cdot w(f) + f' \cdot w(f') }.
\]
Note that this expression is well-defined and positive because $(1 - f) \cdot w(f)> 0$ and $f' \cdot w(f') \ge 0$.
For each pair $f, f'$, we will construct a family of instances such that the fraction of $f'$-flexible voters who disapprove the candidate chosen by $R^w$ becomes arbitrarily close to $g(f, f')$. 
By definition of $\rho$ and $\varphi_s$, there are choices of $f$ and $f' \ge s$ that make this ratio arbitrarily close to
\(
    \frac{\rho}{\rho + \varphi_s},
\)
which establishes the bound. 

Fix such a pair $f,f'$. 
Let $m$ be such that both $\ell := mf$ and $\ell' := mf'$ are integers. 
We will have a special candidate $a^*$, and let $B$ be a set of voters of size $\floor{g(f, f') \cdot n} - m$ (with $n$ sufficiently large that this is nonnegative). 
We will ensure that $a^*$ is the unique candidate with the highest $w$-score, while voters in $B$ are $f'$-flexible and disapprove $a^*$. 
Note that as $n$ grows large, $|B|/n$ approaches the desired bound of $g(f, f')$.

Assume that each voter in $B$ approves $\ell'$ candidates from $M \setminus \set{a^*}$, with the approvals distributed as equally as possible.
Similarly, the voters in $\bar{B} = N\setminus B$ approve $a^*$ along with $\ell - 1$ candidates of $M \setminus \set{a^*}$, again distributed as equally as possible (note that $\ell \ge 1$ because $f > 0$ by assumption). 
Since the voters in $B$ and $\bar{B}$ distribute their approvals as evenly as possible across the candidates in $M \setminus \set{a^*}$, for any such candidate $a$, its score is no more than $w(f') + w(f)$ larger than the average.
Formally,
\[
	\sc^{w}(a) \le \frac{1}{m - 1} \sum_{c \in M \setminus \{a^*\}} \sc^{w}(c) + (w(f') + w(f)).
\]
Hence, it is sufficient to show that
\[
	\sc^{w}(a^*) > \frac{1}{m - 1} \sum_{c \in M \setminus \{a^*\}} \sc^{w}(c) + (w(f') + w(f)).
\]
This is equivalent to showing that
\[
	(m - 1) \sc^{w}(a^*) > \sum_{c \in M \setminus \{a^*\}} \sc^{w}(c) + (m - 1)(w(f') + w(f)).
\]
We have 
\begin{align*}
	(m - 1) \sc^{w}(a^*)
    &= (m - 1) |\bar{B}|\cdot w(f)\\
	&= (\ell - 1) |\bar{B}|\cdot w(f) + (m - \ell)|\bar{B}|\cdot w(f)\\
	&\ge (\ell - 1) |\bar{B}|\cdot w(f) + (m - \ell)\left((1 - g(f, f')) \cdot n + m\right)\cdot w(f)\\
	&= (\ell - 1) |\bar{B}|\cdot w(f) + m \cdot (1 - f)\cdot w(f) \cdot \frac{f' \cdot w(f')}{(1 - f) \cdot w(f) + f' \cdot w(f')} \cdot n  + m \cdot (m - \ell)\cdot w(f)\\
 &= (\ell - 1) |\bar{B}|\cdot w(f) + \ell' \cdot w(f') \cdot g(f, f') \cdot n  + m\cdot (m - \ell) \cdot w(f)\\
 &\ge (\ell - 1) |\bar{B}|\cdot w(f) + \ell' \cdot w(f') \cdot (|B| + m  )  + m\cdot (m - \ell)\cdot w(f)\\
	&= (\ell - 1) |\bar{B}|\cdot w(f) +  w(f') \cdot \ell' \cdot  |B|   + m((m - \ell)\cdot w(f) + \ell \cdot w(f'))\\
	&\ge  (\ell - 1) |\bar{B}|\cdot w(f) +  w(f') \cdot \ell' \cdot  |B|   + m(w(f) + w(f'))\\
    &>  (\ell - 1) |\bar{B}|\cdot w(f) +  w(f') \cdot \ell' \cdot  |B|   + (m - 1)(w(f) + w(f'))\\
    &= \sum_{c \in M \setminus \{a^*\}} \sc^{w}(c) + (m - 1)(w(f') + w(f)),
\end{align*}
where the second-to-last inequality holds because $1\le \ell \le m-1$, and the last inequality holds because $w(f) > 0$.
This completes the proof.
\qed

\subsection{Proof of \Cref{thm:characterization}}

    Fix $w$ and suppose that $R^w$ is \FVR-optimal. 
    By \Cref{thm:general-weight}, this implies that $\frac{\rho}{\rho + \varphi_s} = 1 - s$ for all $s\in (0,1)$, where $\rho = \sup_f (1 - f) \cdot w(f)$ and $\varphi_s = \inf_{f \ge s} f \cdot w(f)$.

    First, we show that $w(f) > 0$ for every $f$. 
    Indeed, since $w$ is nontrivial, there exists $f^* \in \mathbb{Q}\cap (0,1)$ for which $w(f^*) > 0$, so we have $\rho \ge w(f^*) \cdot (1 - f^*) > 0$. 
    Further, if $w(f) = 0$ for some $f$, then $\varphi_f \le w(f) \cdot (1 - f) = 0$. Therefore, 
    \[
        \frac{\rho}{\rho + \varphi_f} \ge 1 > 1 - f,
    \]
    a contradiction.

    We next show that for all flexibilities $f_1, f_2$, it holds that $(1 - f_2) \cdot w(f_2) = (1 - f_1) \cdot w(f_1)$. 
    Fix $f_1, f_2 \in \mathbb{Q} \cap (0, 1)$. 
    By setting $s = f_1$, we have that
    \[
        \frac{\rho}{\rho + \varphi_{f_1}} = 1 - f_1.
    \]
    Note that the ratio $\frac{a}{a + b}$ is increasing in $a$ and decreasing in $b$. Therefore, replacing $\rho$ by a value at most $\rho$ and replacing $\varphi_{f_1}$ with a value larger than $\varphi_{f_1}$ will only decrease the ratio. In particular, by their definitions, $\rho \ge (1 - f_2) \cdot w(f_2)$ and $\varphi_{f_1} \le f_1 \cdot w(f_1)$. Hence,
    \[
        \frac{(1 - f_2) \cdot w(f_2)}{(1 - f_2) \cdot w(f_2) + f_1 \cdot w(f_1)} \le 1 - f_1.
    \]
    As shown before, each $w(f)$ is positive, so the denominator is positive. Multiplying on both sides, we obtain
    \[
       (1 - f_2) \cdot w(f_2) \le (1 - f_1) \cdot ((1 - f_2) \cdot w(f_2) + f_1 \cdot w(f_1)).
    \]
    Distributing and rearranging yields
    \[
        f_1 \cdot (1 - f_2) \cdot w(f_2) \le f_1 \cdot (1 - f_1) \cdot w(f_1).
    \]
    Since $f_1 > 0$, we can divide both sides by $f_1$ to get
    \[
        (1 - f_2) \cdot w(f_2) \le (1 - f_1) \cdot w(f_1).
    \]
    Redoing the entire argument with $f_1$ and $f_2$ flipped yields the reverse inequality, and hence equality.

    With this in hand, let $c := w(1/2) \cdot (1 - 1/2)$. By plugging in $f$ for $f_1$ and $1/2$ for $f_2$, we immediately get that $w(f) = \frac{c}{1 - f}$ for all $f$. \qed

\subsection{Proof of \Cref{thm:multiwinner-lowerbound}}
    Fix $m$, $k$, $s$, and $t$.
    Consider an instance with $n = \binom{m}{\ceiling{sm}}$ voters, each approving a distinct subset of $\ceiling{sm}$ candidates.
    Note that by symmetry, every $k$-committee $W$ is $t$-disapproved by exactly the same number of voters. 
    By \Cref{lem:t-approve} and an averaging argument, this must be a $H(m, \ceiling{sm}, k; t - 1)$-fraction of voters.
    Hence, no matter which committee is selected, an $H(m, \ceiling{sm}, k; t - 1)$-fraction of voters, all of whom are $s$-flexible, will $t$-disapprove. 

    To show tightness, consider a rule that chooses a $k$-committee that is $t$-approved by the highest number of $s$-flexible voters. 
    Note that each $s$-flexible voter approves at least a $(1 - H(m, \ceiling{sm}, k; t - 1))$-fraction of the committees (as approving more than $\ceiling{sm}$ candidates can only increase this value). 
    Hence, by an averaging argument, there must exist a committee approved by at least a $(1-H(m, \ceiling{sm}, k; t - 1))$-fraction of these voters. Therefore, at most an $H(m, \ceiling{sm}, k; t - 1)$-fraction of $s$-flexible voters (and therefore of all voters as well) can $t$-disapprove the chosen committee.
\qed

\subsection{Proof of \Cref{thm:ropt-extended}}
    Fix $k$, $t$, $s$, and an instance with $m$ candidates.
    Let $W$ be the committee chosen by $R^{k, t}_{\text{expanded}}$, and let $B$ be a subset of voters that are $s$-flexible and do not $t$-approve $W$. 
    By \Cref{lem:t-approve}, if a voter is $s$-flexible, then she approves at least a $(1- H(m, \ceiling{sm}, k; t - 1))$-fraction of candidates in the $(k, t)$-expanded instance.
    In other words, the voter is ($1- H(m, \ceiling{sm}, k; t - 1)$)-flexible in the instance on which $\Ropt$ is run. 
    Therefore, \Cref{thm:singlewinner-optimal} guarantees that $|B| \le  H(m, \ceiling{sm}, k; t - 1) \cdot n$.
\qed

\subsection{Proof of \Cref{thm:sequential}}
    Fix $k$, $t$, $m$, and $s$. 
    By \Cref{lem:t-approve}, each voter~$i\in N$ $t$-approves a $(1 - H(m, |A_i|, k; t - 1))$-fraction of $k$-committees. 
    For each $k$-committee $W$, let
    $$\sc(W) :=  \sum_{i : |A_i \cap W| < t} \frac{1}{H(m, |A_i|, k; t- 1)};$$
    note that the sum is taken over all voters who $t$-disapprove $W$.
    Observe that had we run $\Ropt$ on the $(k, t)$-expanded instance, it would choose a committee with the lowest such score. 
    However, a careful inspection of the proof for $\Ropt$ reveals that we do not need to choose a lowest-score committee for the guarantees to hold. 
    Instead, \emph{any} committee with score no greater than the average score already fulfills the guarantee; the minimum is only a convenient choice to ensure this. 
    Formalizing this observation in the multi-winner setting, where the following expectation is taken over all $k$-committees, we have that
    \begin{align*}
        \E[\sc(W)] &= \frac{1}{\binom{m}{k}}\sum_W \sc(W)\\
        &= \frac{1}{\binom{m}{k}} \sum_i \sum_{W: |A_i \cap W| < t} \frac{1}{H(m, |A_i|, k; t- 1)}\\
        &= \frac{1}{\binom{m}{k}} \sum_i \binom{m}{k} \cdot H(m, |A_i|, k; t- 1) \cdot  \frac{1}{H(m, |A_i|, k; t- 1)} = n.
    \end{align*}
    As long as $W$ is such that $\sc(W) \le n$, we claim that it yields \FVR-optimality for $(s,t)$. 
    Indeed, suppose that $B$ is a set of $s$-flexible voters that $t$-disapprove $W$. 
    Then, each voter $i \in B$ contributes $\frac{1}{H(m, |A_i|, k; t- 1)} \ge \frac{1}{H(m, \ceiling{sm}, k; t- 1)}$ points to $\sc(W)$. 
    Since $\sc(W) \le n$, we have $|B| \le n \cdot H(m, \ceiling{sm}, k; t- 1)$.

    It therefore suffices to show that \Cref{alg:sequential} chooses a committee $W$ with $\sc(W) \le n$. 
    Let $a_1, \ldots, a_k$ be the sequence of candidates added to the committee in the $k$ iterations of the loop. 
    For $0\le j\le k$, let $C_j = \set{a_1, \ldots, a_j}$ be the set of the first $j$ candidates, so $C_k$ is the final committee returned by the algorithm. 
    We will show that for each $j\ge 1$, it holds that
    \begin{equation}\label{eq:greedy}
    	a_j \in \argmin_{a \in M \setminus C_{j-1}} \E[\sc(W) \mid C_{j - 1} \cup \set{a} \subseteq W].
    \end{equation}
     In other words, $a_j$ is chosen greedily to minimize $\E[\sc(W) \mid C_j \subseteq W]$. 
     Note that \eqref{eq:greedy} implies that for each $j\ge 1$,
     \[
     	\E[\sc(W) \mid C_j \subseteq W] \le \E[\sc(W) \mid C_{j-1} \subseteq W].
     \]
     Therefore,
     \[
     	\sc(C_k) = \E[\sc(W) \mid C_k \subseteq W] \le \E[\sc(W) \mid C_0 \subseteq W] = \E[\sc(W)] = n,
     \]
     where the first equality holds because $|C_k| = k$ (so conditioning on $C_k \subseteq W$ implies $W = C_k$ with probability $1$), the inequality by a straightforward induction, and the second equality because $C_0 = \emptyset$ (so the conditioning is vacuous).

     To complete the proof, it remains to establish \eqref{eq:greedy}. 
     Fix $a \in M \setminus C_{j-1}$ with $a \ne a_j$. 
     Let $C_j' = C_{j - 1} \cup \set{a}$, i.e., the alternate set had we added $a$ instead of $a_j$. 
     We will show that
     \[
     	\E[\sc(W) \mid C_j \subseteq W] \le \E[\sc(W) \mid C'_j \subseteq W].
     \]
     More specifically, we will show that
     \[
     	\E[\sc(W) \mid C_j \subseteq W] - \E[\sc(W) \mid C'_j \subseteq W] \le 0.
     \]
     Note that the conditional distribution of a uniformly selected $W$ conditioned on some set $T \subseteq W$ is simply uniform over the $\binom{m - |T|}{k - |T|}$ sets containing $T$. 
     Hence,
     \[\E[\sc(W) \mid C_j \subseteq W] - \E[\sc(W) \mid C'_j \subseteq W]= \frac{1}{\binom{m - j}{k - j }}\left(\sum_{W:  C_j \subseteq W} \sc(W) - \sum_{W: C'_j \subseteq W} \sc(W)  \right).
     \]
     Since we only wish to show that this quantity is at most $0$, we can ignore the constant in front and show that the difference of sums is nonpositive. 
     We can remove from both sums all committees $W$ that contain both $a_j$ and $a$ to obtain that the difference is equal to
     \[
     	\sum_{\substack{W:  C_j \subseteq W\\a \notin W}} \sc(W) - \sum_{\substack{W:  C'_j \subseteq W\\ a_j \notin W}} \sc(W).
     \]
     An alternative way to sum over the same sets is to simply sum over all sets $T \subseteq M \setminus (C_{j-1} \cup \set{a_j, a})$ with $|T| = k - j$ and output $C_j \cup T$ or $C'_j \cup T$, respectively. 
     For brevity, we will let $R:=  M \setminus (C_{j-1} \cup \set{a_j, a})$ denote the set of these remaining candidates in neither $C_j$ nor $C'_j$.  
     Hence, the above difference is equal to
     \[
     	\sum_{T} (\sc(C_j \cup T) - \sc(C'_j \cup T)),
     \]
     where the sum is taken over all sets $T\subseteq R$ of size $k-j$.
     Expanding the definition of the score, we get that this is equal to
     \begin{equation}\label{eq:indicators}
		\sum_i \left(\frac{1}{H(m, |A_i|, k; t-1)} \cdot\sum_{T}  (\mathbb{I}[|A_i \cap (C_j \cup T)| < t] - \mathbb{I}[|A_i \cap (C'_j \cup T)| < t])\right).
	\end{equation}
    Note that the sets $A_i \cap (C_j \cup T)$ and $A_i \cap (C'_j \cup T)$ differ in size by at most $1$, and the difference is $1$ when exactly one of $a_j$ and~$a$ is contained in $A_i$. 
    More specifically, either $a_j \in A_i$ and $a \notin A_i$ (in which case the first is larger by $1$) or vice versa (in which case the second is larger by $1$). 
    Hence, the only scenarios in which the difference of indicators is nonzero is when exactly one of $a_j$ and $a$ is in $A_i$, and moreover $|A_i \cap (C_{j-1} \cup T)| = t - 1$; the latter condition can be rewritten as $|A_i \cap T| = t - 1 - |A_i \cap C_{j-1}|$. 
    If $a_j \in A_i$, the difference is $-1$, while if $a \in A_i$, the difference is $1$.

    Fix a voter $i$ such that exactly one of $a_j$ and $a$ is contained in $A_i$, and consider the number of sets $T \subseteq R$ of size $k-j$ such that $|A_i \cap T| = t - 1 - |A_i \cap C_{j-1}|$. We claim that it is $\binom{m-j-1}{k-j}$ times $h(m - j - 1,\, |A_i \setminus C_{j-1}| - 1,\, k - j;\, t - 1 - |A_i \cap C_{j-1}|)$. 
    Indeed, it is exactly the probability of choosing a random set $T$ of size $k - j$ from a set $R$ of size $m - j - 1$ (recall that $R = M \setminus (C_{j - 1} \cup \set{a_j, a})$) which contains $|A_i \cap R| = |A_i \setminus (C_{j - 1} \cup \set{a_j, a})| = |A_i \setminus C_{j - 1}| - 1$ elements of $A_i$, and ending up with $|A_i\cap T| = t - 1 - |A_i \cap C_{j - 1}|$  such elements. 
    Putting this together, we have that as long as exactly one of $a_j$ and $a$ is in $A_i$, the entire inner sum is $\binom{m-j-1}{k-j}$ times
    \begin{equation}\label{eq:indicators-2}
    	(\mathbb{I}[a \in A_i] - \mathbb{I}[a_j \in A_i]) \cdot h(m - j - 1,\, |A_i \setminus C_{j-1}| - 1,\, k - j;\, t - 1 - |A_i \cap C_{j-1}|).
    \end{equation}
    In fact, \eqref{eq:indicators-2} continues to hold even when not exactly one of $a_j$ and $a$ is in $A_i$, as the difference in indicators is simply $0$ in that case. 
    Hence, \eqref{eq:indicators} is $\binom{m-j-1}{k-j}$ times
    \[
    	\sum_i \left((\mathbb{I}[a \in A_i] - \mathbb{I}[a_j \in A_i])\cdot \frac{h(m - j - 1,\, |A_i \setminus C_{j-1}| - 1,\, k - j;\, t - 1 - |A_i \cap C_{j-1}|)}{H(m, |A_i|, k; t-1)}\right).
    \]
    Note that the probability mass function and cumulative distribution function ratio is exactly the weight $w_i$ given to voter $i$ in the round where $a_j$ is chosen in \Cref{alg:sequential}.
    Rewriting the expression above, we see that this is equal to
    \[
    	\sum_{i: a \in A_i} w_i - \sum_{i: a_j \in A_i} w_i.
    \]
    Since $a_j$ is a candidate with the highest weighted approval when it is chosen, this difference is at most $0$, as desired. \qed


\subsection{Proof of \Cref{thm:impossibility-simultaneous-t}}

Consider an instance with $m = 2k$ candidates partitioned into two sets $C_1$ and $C_2$, each of size $k$. 
Suppose that half of the voters approve only $C_1$, and the other half approve only $C_2$. 
Note that all voters are $1/2$-flexible.

Fix any rule $R$. If $R$ is FVR-optimal for $(1/2, k)$, the chosen committee must be $k$-approved by a nonzero fraction of voters, i.e., it must consist entirely of either $C_1$ or $C_2$. 
However, this means that $R$ cannot be FVR-optimal for $(1/2, t)$. 
Indeed, the other half of the voters do not $t$-approve this committee (and are $1/2$-flexible), so $\text{FVR}(R, 1/2, t, m) \ge 1/2$.
On the other hand, the optimal value is $H(2k, k, k; t - 1) < 1/2$. 
Indeed, it is precisely the probability that these $1/2$-flexible voters do not $t$-approve a randomly chosen committee of size $k$. 
Since $t \le \lfloor k / 2 \rfloor$, by symmetry, this probability is strictly less than $1/2$. 
\qed

\subsection{Proof of \Cref{thm:jr-impossibility}}
    Take some $m > k$. 
    Suppose that the candidates are partitioned into two sets $B \cup C$, where $B = \set{b_1, \ldots, b_{k-1}}$ and $C = \set{c_1, \ldots, c_{m - k + 1}}$. 
    There are $k$ groups of voters, $N_1, \ldots, N_k$, each of size $m - k + 1$.
    For $1\le j\le k-1$, each voter in $N_j$ approves $b_j$ and no other candidate.
    Each voter in $N_k$ approves all candidates in $C$ except one, a distinct one per voter. 

    Observe that for a committee $W$ to satisfy JR, we must have $B \subseteq W$. 
    Indeed, if not, there is some $j$ such that $b_j \notin W$, and the set $N_j$ forms a blocking coalition. 
    However, once $B \subseteq W$, we have $|W \cap C| = 1$. 
    Hence, there exists a voter in $N_k$ who disapproves the unique candidate from $C$ in $W$, and therefore disapproves the entire committee. 
    This voter is $\frac{m - k}{m}$-flexible and comprises a $\frac{1}{k \cdot (m - k + 1)} \ge \frac{1}{km}$ fraction of the voters. 
    Note that the optimal \FVR guarantee for $s = \frac{m-k}{m}$ and $t = 1$ is $H(m, m-k, k; 0) = \frac{1}{\binom{m}{k}}$. 
    For sufficiently large $m$, we have $\binom{m}{k} > km$, so the optimal \FVR guarantee for $(s,t) = (\frac{m-k}{m},1)$ is incompatible with JR.
\qed


\section{Proportional Veto Core}
\label{app:PVC}

In this appendix, we define a stronger version of proportional veto core in the same spirit as our FVR notion, and show that it can sometimes be empty.

\begin{definition}
Given $n$ voters with strict rankings over $m$ candidates, a candidate $a$ is \emph{weakly vetoed} by a group $N'$ of voters if each voter in $N'$ prefers at least $m - \lceil m\cdot |N'|/n\rceil + 1$ candidates to $a$.

The \emph{strong proportional veto core} consists of all candidates that are not weakly vetoed by any group of voters.
\end{definition}

Note that in the original proportional veto core \citep{Moul81}, a candidate $a$ is vetoed by a group of voters $N'$ if all voters in $N'$ prefer the \emph{same} set of $m - \lceil m\cdot |N'|/n\rceil + 1$ candidates to $a$.

\begin{proposition}
The strong proportional veto core can be empty.
\end{proposition}

\begin{proof}
Consider $m = 3$ candidates and $n = 2$ voters with rankings $a\succ b\succ c$ and $c\succ b\succ a$.
\begin{itemize}
\item Candidate $c$ is vetoed by voter~$1$, since the voter prefers $3 - \lceil 3\cdot 1/2\rceil + 1 = 2$ candidates to $c$.
\item Similarly, candidate $a$ is vetoed by voter~$2$.
\item Candidate $b$ is vetoed by both voters together, since each voter prefers $3 - \lceil 3\cdot 2/2\rceil + 1 = 1$ candidate to $b$.
\end{itemize}
Hence, the strong proportional veto core is empty in this instance.
\end{proof}

