\section{Bound for the support and its sharpness}\label{sec:main_results}


\begin{theorem}[Bound for the support]\label{theorem_general_specialized}
    Let $g_1, \ldots, g_n$ be polynomials in $\mathbb{K}[x_1, \ldots, x_n] = \mathbb{K}[\mathbf{x}]$ 
    such that $d := \deg g_1 > 0$ and $D := \max_{2 \leqslant i \leqslant n}\deg g_i > 0$.
    Let $I := \ideal{\mathbf{x}' - \mathbf{g}}^{(\infty)}$ and let $f_{\min} \in \mathbb{K}[x_1^{(\infty)}]$ be the minimal polynomial of $I \cap \mathbb{K}[x^{(\infty)}_1]$.
    Consider a positive integer $\nu$ such that $\ord f_{\min} \leqslant \nu$ ($\nu = n$ can be always used).

    Then  for every monomial  $x_1^{e_0} (x'_1)^{e_1} \ldots (x^{(\nu)}_1)^{e_\nu}$ in $f_{\min}$ the following inequalities hold

    \begin{enumerate}
        \item\label{case:d1_leq_D} If $d \leqslant D$, then
            \begin{equation} \label{eq:bound_1}
                e_0 + \sum_{k=1}^{\nu} \bigl(d + (k - 1)(D - 1) \bigr) e_k \leqslant \prod_{k=1}^{\nu} \bigl(d + (k - 1)(D - 1)\bigr);
            \end{equation}
        \item\label{case:d1_ge_D} If $d > D$, then for every $0 \leqslant \ell < \nu$, we have
           \begin{equation} \label{eq:bound_2}
                \begin{split}
                     & \sum_{k=0}^{\ell} \bigl(k(D - 1) + 1 \bigr) e_k + \sum_{i=1}^{\nu - \ell} \bigl( i (d - 1) + \ell (D - 1) + 1\bigr) e_{i + \ell} \leqslant \\
                     & \quad \leqslant \prod_{k = 1}^{\ell} \bigl(d + (k - 1) (D - 1) \bigr) \prod_{i=1}^{\nu - \ell} \bigl( i (d - 1) + \ell (D - 1) + 1\bigr).
                \end{split}
             \end{equation}
    \end{enumerate}
\end{theorem}

The corresponding polytopes in the planar case $n = 2$ are shown on Figure~\ref{fig:2d}.



\begin{notation}
 Let $V_{n, d}$ be the space of polynomials of degree at most $d$ in the variables $\mathbf{x} = \tuple{x_1, \ldots, x_n}$ over the field $\mathbb{K}$.
\end{notation}

\begin{theorem}[Generic sharpness in the planar case]\label{thm:2d}
    Let $d_1, d_2 \in \mathbb{Z}_{> 0}$.
    Then there exists a nonempty Zariski open subset $U \subset V_{2, d_1} \times V_{2, d_2}$ such that, for every pair of polynomials  $\tuple{g_1, g_2} \in U$, the Newton polytope of the minimal polynomial $f_{\min}$ of the differential ideal
    \[I \cap \mathbb{K}[x_1^{(\infty)}],\quad \text{where } I = \ideal{x_1' - g_1(x_1, x_2), x_2' - g_2(x_1, x_2)}^{(\infty)}
    \]
    is the one given by Theorem~\ref{theorem_general_specialized} with $\nu = n = 2$ (see also Figure~\ref{fig:2d}).

    In this particular case, the Newton polytope of $f_{\min}$ is given by the following inequalities (on the exponents of $x_1^{e_0} (x'_1)^{e_1}(x''_1)^{e_2}$)
     \begin{enumerate}
        \item If $d_1 \leqslant d_2$, then
        \begin{equation} \label{eq0001}
        e_0 + d_1 e_1 +(d_1 + d_2 - 1)e_2 \leqslant d_1(d_1 + d_2 - 1);
        \end{equation}

        \item If $d_1 > d_2$, then
        \begin{equation} \label{eq0002}
            \begin{split}
                &  e_0 + d_1 e_1 +(2d_1-1) e_2 \leqslant d_1(2d_1-1),\\
                &  e_0 + d_2 e_1  +(d_1+d_2-1)e_2 \leqslant d_1(d_1+d_2-1).
            \end{split}
        \end{equation}  
    \end{enumerate}
    \end{theorem}

