\section{Proofs: general facts and notation}\label{sec:proofs:general}

In this section we will explain how we reduce the differential elimination problem to a polynomial elimination problem.
This construction will be then used both in the proof of the bound for the support (Theorem~\ref{theorem_general_specialized}) and in the proof of its sharpness (Theorems~\ref{thm:2d} and~\ref{thm:sharp})

We will fix some notation used throughout the rest of the paper.

\begin{notation}\label{not:proofs_notation}
    Consider an ODE system $\bx' = \bg(\bx)$ with $\bx = \tuple{x_1, \ldots, x_n}$ and $g_1, \ldots, g_n \in \KK[\bx]$.
    \begin{itemize}
        \item  The differential ideal $\ideal{\bx' - \bg}^{(\infty)} \subset \KK[\bx^{(\infty)}]$ will be denoted by $I_{\bg}$.
        \item We denote the Lie derivative operator $\mathcal{L}_{\bg} \colon \KK[\bx] \to \KK[\bx]$ by $\mathcal{L}_{\bg} := \sum\limits_{i=1}^{n} g_i \frac{\partial}{\partial x_i}$.

        \item We define the operator $\mathcal{L}^\ast_{\bg} \colon \KK[x_1^{(\infty)}, x_2, \ldots, x_n] \to \KK[x_1^{(\infty)}, x_2, \ldots, x_n]$ by the formula
        \begin{equation}\label{eq:opD}
        \mathcal{L}^\ast_{\bg} := \sum\limits_{i=2}^{n} g_i \frac{\partial}{\partial x_i} + \sum\limits_{i=0}^{\infty} x_1^{(i+1)}\frac{\partial}{\partial x_1^{(i)}}.
        \end{equation}

        \item We define the reduction homomorphism $\mathcal{R}_{\bg} \colon \KK[\bx^{(\infty)}] \to \KK[\bx]$ by $\mathcal{R}_{\bg}(x_i^{(j)}) := \mathcal{L}_{\bg}^j (x_i)$.
    \end{itemize}
\end{notation}

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

Next in the section we consider an ODE system:
\begin{equation}\label{eq:sigma_general}
\bx' = \bg(\bx), \quad \text{ where } \bx = \tuple{x_1, \ldots, x_n} \text{ and } g_1, \ldots, g_n \in \KK[\bx].
\end{equation}


The following lemma shows that the problem of computing the minimal polynomial of the differential elimination ideal $I_{\bg} \cap \KK[x_1^{(\infty)}]$ can be reduced to a polynomial elimination problem for polynomials
\[
  x_1' - g_1, \; \mathcal{L}_{\bg}^\ast(x_1' - g_1), \ldots, \; (\mathcal{L}_{\bg}^\ast)^{\nu - 1}(x_1' - g_1),
\]
where $\nu$ is the order of the minimal differential polynomial for $x_1$.

\begin{lemma} \label{lem:ideal_is_wanted}
 For the system~\eqref{eq:sigma_general} for every $s \geqslant 0$:
    \[
    \ideal{x'_1 - g_1, \mathcal{L}^\ast_{\bg}(x_1' - g_1), \ldots, (\mathcal{L}_{\bg}^\ast)^s(x_1' - g_1) } = I_{\bg} \cap \mathbb{K}[x_1^{(\leqslant s + 1)}, x_2, \ldots, x_n].
    \]
    Furthermore, this ideal is also equal to $\ideal{ x_1' - g_1, x_1'' - \mathcal{L}_{\bg}(g_1), \ldots, x_1^{(s+1)} - \mathcal{L}^s_{\bg}(g_1)}$.
\end{lemma}

\begin{corollary}
    The minimal differential polynomial in $I_{\bg} \cap \KK[x_1^{(\infty)}]$ is the generator of the principal ideal $\ideal{x_1 - g_1, \mathcal{L}_{\bg}^\ast(x_1' - g_1), \ldots, (\mathcal{L}_{\bg}^\ast)^{\nu - 1}(x_1' - g_1)}$.
\end{corollary}

\begin{proof}[Proof of Lemma~\ref{lem:ideal_is_wanted}]
    Denote 
    \[
    J := \ideal{x_1' - g_1, \mathcal{L}_{\bg}^\ast(x_1'  - g_1), \ldots, (\mathcal{L}_{\bg}^\ast)^s(x_1' - g_1)} \subset \KK[x_1^{(\leqslant s + 1)}, x_2, \ldots, x_n].
    \]
    We observe that, for $f \in I_{\bg} \cap \KK[x_1^{(\infty)}, x_2, \ldots, x_n]$, we have
    \[
    \mathcal{L}_{\bg}^\ast (f) = f' - \sum\limits_{i = 2}^n (x_i' - g_i) \frac{\partial f}{\partial x_i} \in I_{\bg}.
    \]
    Since $x_1' - g_1 \in I_{\bg}$, we have $J \subset I_{\bg} \cap \KK[x_1^{(\leqslant s + 1)}, x_2, \ldots, x_n]$.
    For the reverse inclusion, assume for contradiction that there exists a $p \in I_{\bg} \cap \mathbb{K}[x_1^{(\leqslant s + 1)}, x_2, \ldots, x_n]$ with $p \not\in J$. 
    We fix the monomial ordering on $\KK[x_1^{(\leqslant s + 1)}, x_2, \ldots, x_n]$ to be the lexicographic monomial ordering with 
    \[
    x_1^{(s + 1)} > x_1^{(s)} > \ldots > x'_1 > x_1 > x_2 > \ldots > x_n.
    \]
    The leading term of $(\mathcal{L}_{\bg}^\ast)^i(x_1' - g_1)$ is $x_1^{(i + 1)}$.
    Therefore, the leading terms of all generators of $J$ are distinct variables. 
    Hence this set is a Gr\"obner basis of $J$
    by the first Buchberger criterion~\cite{buchberger1979criterion}. 
    Then the result of the reduction of $p$ with respect to the Gr\"obner basis belongs to $\mathbb{K}[\mathbf{x}]$ and is distinct from zero.  
    Thus, we get a contradiction with $p \in I_{\bg}$ because $I_{\bg} \cap \KK[\mathbf{x}] = \{0\}$ by~\cite[Lemmas 3.1 and 3.2]{hong2020global}.

    Since the argument above applies verbatim if we use $\mathcal{L}_{\bg}$ instead of $\mathcal{L}_{\bg}^\ast$, $J$ coincides with $\ideal{x_1' - g_1, x''_1 - \mathcal{L}_{\bg}(g_1), \ldots, x_1^{(s+1)} - \mathcal{L}^s_{\bg}(g_1)}$.
\end{proof}

The following lemma will be used to reduce the differential ideal membership to a polynomial substitution.

\begin{lemma}[{cf. \cite[Remark 7]{DAlfonso2006}}] \label{lem::substitution}
    For the system~\eqref{eq:sigma_general} we have $\ker(\mathcal{R}_{\bg}) = I_{\bg}$.
\end{lemma}

\begin{proof}
  Let the dimension of the ODE system be $n$.
  Denote by $\prec$ the lexicographic monomial ordering on $\KK[\mathbf{x}^{\infty}]$ given by the variable ordering $x_j^{(i)}\prec x_k^{(l)}$ iff $i > l$ or $(i = l)\;\&\;(j<k)$.
  Note that the set $G:=\{ x_j^{(i)} - \mathcal{L}_{\bg}^i(g_j) \}_{1 \leqslant j \leqslant n, i \geqslant 1}$ is a Gröbner
  basis of $I_{\bg}$ w.r.t. $\prec$ by the first Buchberger criterion since the leading terms of all elements of $G$ are distinct variables . 
  This yields an isomorphism
  \[
  \mathbb{K}[x_1^{(\infty)},\ldots, x_n^{(\infty)}] / I_{\bg} \simeq \mathbb{K}[x_1,\ldots, x_n]
  \]
  of $\mathbb{K}$-algebras induced by sending any
  $g\in \mathbb{K}[x_1^{(\infty)},\ldots, x_n^{(\infty)}]$ to its normal form
  w.r.t. $G$.

  On the other hand, $\mathcal{R}_{\bg}(f)\in \mathbb{K}[x_1,\dots,x_n]$ and
  $f-\mathcal{R}_{\bg}(f)\in I_{\bg}$. 
  Hence $\mathcal{R}_{\bg}(f)$ must be the normal form of
  $f$ w.r.t. $G$ and $\prec$ because the monomials in $x_1,\dots,x_n$ form
  a $\mathbb{K}$-vector space basis of
  $\mathbb{K}[x_1^{(\infty)},\ldots, x_n^{(\infty)}] / I_{\bg}$. 
  But then
  $f\in I_{\bg}$ if and only if $\mathcal{R}_{\bg}(f) = 0$.
\end{proof}

