\section{Proofs: the bound for the support}\label{sec:proofs_bound}

\subsection{Weighted B\'ezout bound}

\begin{lemma} \label{lem:square_free}
    Let $g $ be a square-free polynomial in $\mathbb{K}[\mathbf{x}, y] = \mathbb{K}[x_1, \ldots, x_n, y]$. Then for every $\omega \in \mathbb{Z}_{\geqslant 0}$ there exists a homomorphism $\varphi$
    \[
    \varphi: \mathbb{K}[\mathbf{x}, y] \rightarrow \mathbb{K}[\mathbf{x}, z]
    \]
    with $\varphi(x_i) = x_i$ and $\varphi(y) = p(z)$, where $p \in \mathbb{K}[z]$, $\deg p = \omega$, such that the polynomial $\varphi(g)$ is square-free.
\end{lemma}

\begin{proof}
    Let us consider the cases $\omega = 0$ and $\omega > 0$ of the lemma separately.

    Assume $\omega = 0$. For every $x_i$ let us consider the discriminant $D_i := \Disc_{\!x_i} \; (g(\mathbf{x}, y))$. 
    Since $g$ is square-free, $D_i$ is a nonzero polynomial in $\mathbb{K}(\mathbf{x})[y]$ for every $i$. 
    Let us denote by $A$ the set of zeros $ \{ \alpha_1, \ldots, \alpha_m \}$ of the polynomials $D_1, \ldots, D_n$. 
    It thus suffies for any homomorphism $\varphi$ satisfying $\varphi(y) = a$ for $a \in \mathbb{K} \setminus A$. 


    Consider the case $\omega > 0$. 
    First of all note that since $g$ is square-free $g(\mathbf{x}, p(z))$ can not be divisible by a square of a polynomial in $\mathbb{K}[\mathbf{x}]$. 
    Indeed, if that was the case then $g(\mathbf{x},y)$ would be divisible by the same square. 
    Then to ensure that $\varphi(g)$ is square-free we consider
    \[
    D := \Disc_{\!z} \bigl(g(\mathbf{x}, p(z))\bigr).
    \]
    Since $\frac{\partial}{\partial z} g(\mathbf{x}, p(z)) = Q_1 Q_2$ for $Q_1 := (\frac{\partial}{\partial y} g(\mathbf{x},y))_{y = p(z)}$ and $Q_2 := \frac{\partial}{\partial z} p(z)$, then 
    \[
    D = \Res_{\!z} (g(\mathbf{x}, p(z)), Q_1) \Res_{\!z}(g(\mathbf{x}, p(z)), Q_2). 
    \]
    Since $g$ is square-free,
    \[
    \Res_{\!z}\bigl(g(\mathbf{x}, p(z)), Q_1\bigr)=\Res_{\!z}\bigl(g(\mathbf{x}, y)_{y = p(z)}, (\frac{\partial}{\partial y} g(\mathbf{x},y))_{y = p(z)}\bigr) = \varphi \bigl(\Disc_{\!y}(g(\mathbf{x}, y))\bigr)
    \]
    is nonzero. 

    Let $\varphi(y)$ be $z^{\omega} + a$ for $a \in \mathbb{K}$. 
    Since $\mathbb{K}$ is infinite, we can choose values $a_i \in \mathbb{K}$ such that $\tilde{g}(y) := g(a_1, \ldots, a_n, y) \neq 0$. 
    Then over $\overline{\mathbb{K}}$ we have $\tilde{g}(z^\omega) =\prod\limits_{i=1}^N(z^\omega - \alpha_i)$. Let us choose $a \notin \{ \alpha_1, \ldots, \alpha_N \}$. Then $z$ does not divide $\tilde{g}(z^\omega - a)$ and hence also does not divide $g(\mathbf{x},\varphi(y))$. We conclude that
    \[
    \Res_{\!z}\bigl(g(\mathbf{x}, p(z)), Q_2\bigr) = \Res_{\!z}\bigl(g(\mathbf{x}, p(z)), \omega z^{\omega - 1}\bigr)
    \]
    is nonzero, finishing the proof.
\end{proof}

\begin{lemma} \label{lem:multivariate_square_free}
    Let $g $ be a square-free polynomial in $\mathbb{K}[\mathbf{x}, \mathbf{y}] = \mathbb{K}[x_1, \ldots, x_n, y_1, \ldots, y_k]$. Then for every $\tuple{\omega_1, \ldots, \omega_k} \in \mathbb{Z}_{\geqslant 0}^k$ there exists a homomorphism $\varphi$
    \[
    \varphi: \mathbb{K}[\mathbf{x}, \mathbf{y}] \rightarrow \mathbb{K}[\mathbf{x}, z_1, \ldots, z_k]
    \]
    with $\varphi(x_i) = x_i$ and $\varphi(y_i) = p_i(z_i)$, where $p_i \in \mathbb{K}[z_i]$ and $\deg p_i(z_i) = \omega_i$ such that the polynomial $\varphi(g)$ is square-free.
\end{lemma}
\begin{proof}
We will show this by induction on $k$. 
The base case $k=1$ follows from Lemma~\ref{lem:square_free}. 

We fix $k > 1$ and substitute $y_1,\ldots,y_{k-1}$ with $p_1(z_1), \ldots, p_{k-1}(z_{k-1})$ in $g$, by the induction hypothesis the resulting polynomial $\tilde{g}$ is square-free. 
Now the statement follows for $k$ by applying Lemma \ref{lem:square_free} to $\tilde{g}$ with $\bx$ being $\mathbf{x}\cup \{z_1,\ldots,z_{k-1}\}$ and $y$ being $y_k$. 
\end{proof}

\begin{lemma} \label{lem:total_degree}
    Let $p_1, \ldots, p_n$ be polynomials of degrees $d_1, \ldots, d_n$ in $\mathbb{K}[\mathbf{x}, \mathbf{y}]$ 
    with  $\bx = \tuple{x_1, \ldots, x_{m}}$ and $\by = \tuple{y_1, \ldots, y_k}$.
    Suppose that the ideal $I = \ideal{p_1, \ldots, p_n} \cap \mathbb{K}[\mathbf{y}]$ is principal, that is,
    $I = \ideal{g}$, and let $g = g(\mathbf{y})$ be a nonzero square-free polynomial. 
    Then 
    $\deg g \leqslant \prod_{i = 1}^n d_i$.
\end{lemma}

\begin{proof}

Let us consider the algebraic variety $X := \mathbb{V} (p_1, \ldots, p_n) \subset \mathbb{A}^{m+k}$. Since $X = \mathbb{V}(p_1) \cap \ldots \cap \mathbb{V}(p_n)$, then for the degree of variety $X$ by ~\cite[Theorem~1]{cox2005using} we have 
\[
\deg X \leqslant \prod\limits_{i=1}^n \deg \mathbb{V}(p_i) = \prod\limits_{i=1}^n \deg p_i = \prod\limits_{i=1}^n d_i.
\]
Denote by $\pi: \mathbb{A}^{m+k} \rightarrow \mathbb{A}^{k}$ the projection onto the last $k$ components. 
Then by~\cite[Chapter 4, \S4, Theorem~3]{cox1997ideals} $\mathbb{V}(I) \subset \mathbb{A}^k$ is the Zariski closure of $\pi (X)$ and since $I$ is the principal ideal generated by a square-free polynomial $g$, we obtain $\mathbb{V}(g) =  \overline{ \pi (X)}$ and $\deg \overline{ \pi (X)} = \deg g$ \cite[ Chapter 9, \S 4, Exercise~12]{cox1997ideals}.

Applying~\cite[Lemma~2]{heintz1983definability} to the projection $\pi$ and the algebraic variety $X$ we obtain $\deg \overline{\pi (X)} \leqslant \deg X$. So
\[
   \deg g = \deg \overline{\pi (X)} \leqslant \deg X \leqslant \prod\limits_{i=1}^{n} d_i.\qedhere
\]  
\end{proof}

