\subsection{Bound for the support in a general form}

We will derive Theorem~\ref{theorem_general_specialized} from the following more general bound.


\begin{theorem} \label{theorem_general}
    Let $g_1, \ldots, g_n$ be polynomials in $\mathbb{K}[x_1, \ldots, x_n] = \mathbb{K}[\mathbf{x}]$  with $d := \deg g_1 > 0$ and $D := \max_{2 \leqslant i \leqslant n}\deg g_i > 0$.
    Let $f_{\min} \in \mathbb{K}[x_1^{(\infty)}]$ be the minimal polynomial of $I_{\bg} \cap \mathbb{K}[x^{(\infty)}_1]$ and consider a positive integer $\nu$ such that
    $\ord f_{\min} \leqslant \nu$.

    Then for every vector $(\omega_1, \ldots, \omega_\nu) \in (\mathbb{Z}_{\geqslant 0})^{\nu}$ and every monomial  $x_1^{e_0} (x'_1)^{e_1} \ldots (x^{(\nu)}_1)^{e_\nu}$ in $f_{\min}$, the following inequality holds
    \begin{equation}\label{eq:theorem_general_bound}
         e_0 + \sum_{i=1}^{\nu} \omega_{i} e_i \leqslant \prod_{k=1}^\nu \max \biggl( \omega_k, d + (k-1)(D - 1), \max_{ 1 \leqslant j < k} \bigl(d + \dfrac{k-1}{j} (\omega_j - 1) \bigr) \biggr)
    \end{equation}
\end{theorem}

We will first introduce the necessary notations and prove a few preliminary lemmas that are essential for the proof of Theorem~\ref{theorem_general}.

We consider the set of polynomials defined by 
    \begin{equation} \label{derivatives}
        h_1 := g_1, \quad  h_i := \mathcal{L}_{\bg}^\ast h_{i-1}.
    \end{equation}

\begin{notation} 
    For vectors $\balpha = \tuple{\alpha_1, \ldots, \alpha_n} \in \mathbb{Z}_{\geqslant 0}^n$ and $\bbeta = \tuple{\beta_1, \ldots, \beta_n} \in \mathbb{Z}_{\geqslant 0}^n$, we denote
    \begin{align*}
    m(\balpha, \bbeta) &:= x_1^{\beta_1} \ldots x_n^{\beta_n} (x_1')^{\alpha_1} \ldots (x_1^{(n)})^{\alpha_n},\\
    \ell_1(\balpha, \bbeta) &:= \sum\limits_{i = 1}^n \beta_i + \sum\limits_{i = 1}^n (iD - i + 1) \alpha_i,\\
    \ell_2(\balpha) &:= \sum\limits_{i = 1}^n i\alpha_i.
    \end{align*}
\end{notation}

\begin{lemma} \label{lem:base_operator}
    For every monomial $m(\balpha, \bbeta)$ and every monomial $m(\tilde{\balpha}, \tilde{\bbeta})$ in $\mathcal{L}_{\bg}^\ast(m(\balpha, \bbeta))$, the following inequalities hold:
    \[
    \ell_1(\tilde{\balpha}, \tilde{\bbeta}) \leqslant \ell_1(\balpha, \bbeta) + D - 1 \quad \text{ and } \quad \ell_2(\tilde{\balpha}) \leqslant \ell_2(\balpha) + 1.
    \]
\end{lemma}
\begin{proof}
  Note that
  \[
  \mathcal{L}_{\bg}^\ast(m(\balpha, \bbeta)) = \sum\limits_{i=2}^{n}g_i \frac{\partial}{\partial x_i} m(\balpha, \bbeta) + \sum\limits_{i=0}^{\infty} x_1^{(i+1)} \frac{\partial}{\partial x_1^{(i)}} m(\balpha, \bbeta).
  \]
  Thus, for a monomial $m(\tilde{\balpha}, \tilde{\bbeta})$ in $\mathcal{L}_{\bg}^\ast(m(\balpha, \bbeta))$ we have two options (below $\sim$ stands for the proportionality up to a constant):
  \begin{enumerate}
      \item $m(\tilde{\balpha}, \tilde{\bbeta}) \sim m_1 \frac{\partial}{\partial x_i} m(\balpha, \bbeta)$ for some $2 \leqslant i \leqslant n$ and some monomial $m_1$ in $g_i$.
      \item $m(\tilde{\balpha}, \tilde{\bbeta}) \sim x_1^{(i+1)} \frac{\partial}{\partial x_1^{(i)}} m(\balpha, \bbeta)$ for some $0 \leqslant i \leqslant n$.
  \end{enumerate}

  Consider the first option. In this case, $ \tilde{\balpha} = \balpha$ and $|\tilde{\bbeta}| \leqslant |\bbeta| + D - 1$. Thus, we get 
  \[
  \ell_1(\tilde{\balpha}, \tilde{\bbeta}) \leqslant \ell_1(\balpha, \bbeta) + D - 1 \quad \text{ and } \quad \ell_2(\tilde{\balpha}) = \ell_2(\balpha) \leqslant \ell_2(\balpha) + 1.
  \]

  Consider the second option. 
  If $i = 0$, then $m(\tilde{\balpha}, \tilde{\bbeta}) = x_1' \frac{\partial}{\partial x_1} m(\balpha, \bbeta)$. 
  So, $\tilde{\beta}_1 = \beta_1 - 1$ and $\tilde{\alpha}_1 = \alpha_1 + 1$. Hence,
  \[
  \ell_1(\tilde{\balpha}, \tilde{\bbeta}) \leqslant \ell_1(\balpha, \bbeta) + D - 1 \quad \text{ and } \quad \ell_2(\tilde{\balpha}) = \ell_2(\balpha) + 1.
  \]

  For $1 \leqslant i \leqslant n$ we have $m(\tilde{\balpha}, \tilde{\bbeta}) = x_1^{(i+1)} \frac{\partial}{\partial x_1^{(i)}} m(\balpha, \bbeta)$. 
  So, $\tilde{\alpha}_i = \alpha_i - 1$, $\tilde{\alpha}_{i+1} = \alpha_{i+1} + 1$ and $\tilde{\bbeta} = \bbeta$. 
  Thus,
  \[
    \ell_1(\tilde{\balpha}, \tilde{\bbeta}) \leqslant \ell_1(\balpha, \bbeta) + D - 1 \quad \text{ and } \quad \ell_2(\tilde{\balpha}) = \ell_2(\balpha) + 1.
  \]
  This concludes the proof.
\end{proof}

\begin{corollary} \label{cor:polyhedron}
    For every monomial $m(\balpha, \bbeta)$ in $h_k$, the following inequalities hold:
    \[
    \ell_1(\balpha, \bbeta) \leqslant d + (k - 1)(D - 1)\quad \text{ and } \quad \ell_2(\balpha) \leqslant k - 1.
    \]
\end{corollary}
\begin{proof}
    We observe that $g_1$ is a polynomial of degree at most $d$ in $x_1, \ldots, x_n$, so for every monomial $m(\balpha, \bbeta)$ in $h_1$ we have 
    \[
    \ell_1(\balpha, \bbeta) \leqslant d \quad \text{ and } \quad \ell_2(\balpha) = 0.
    \]

    Consider $h_k = \mathcal{L}_{\bg}^\ast h_{k-1} = (\mathcal{L}_{\bg}^\ast)^{k-1} (h_1)$.
    Then for every monomial $m(\tilde{\balpha}, \tilde{\bbeta})$ in $h_k$ by applying $k-1$ times Lemma~\ref{lem:base_operator} to every monomial $m(\balpha, \bbeta)$ in $h_1$
    we obtain the desired. 
\end{proof}

\begin{lemma} \label{lem:max}
   Consider $\bomega = \tuple{\omega_1, \ldots, \omega_n} \in \mathbb{Z}_{>0}^n$.
   Let $L\colon \mathbb{R}^n\times \mathbb{R}^n \rightarrow \mathbb{R}$ be the linear function defined by
   \[
     L(\balpha, \bbeta) := \sum_{i=1}^{n} \omega_i \alpha_i + \sum_{i=1}^{n} \beta_i.
   \]
  And let $P_k\subset \mathbb{R}^n\times \mathbb{R}^n$, $k \geqslant 1$ be the polyhedron defined by the inequalities
    \begin{equation} \label{eq:polyhedron_P_k}
         \ell_1(\balpha, \bbeta) \leqslant  d + (k-1)(D - 1), \quad \ell_2(\balpha) \leqslant k - 1, \quad \alpha_i, \beta_i \geqslant 0.
    \end{equation}
    Then we have
     \[
    \max_{(\balpha, \bbeta) \in P_k} L(\balpha, \bbeta) = \max \biggl(d + (k-1)(D - 1), \;\;\max_{ 1 \leqslant j < k} \bigl(d + \dfrac{k-1}{j} (\omega_j - 1) \bigr) \biggr).
    \]
\end{lemma}  
\begin{proof}
First of all, let us consider the case $k = 1$.
Then $P_1$ is defined by the inequalities
\[
  \ell_1(\balpha, \bbeta) \leqslant  d,\quad \ell_2(\balpha) \leqslant 0, \quad \alpha_i, \beta_i \geqslant 0.
\]
Since $\ell_2(\balpha) \leqslant 0$ and $\alpha_i \geqslant 0$, we find $\alpha_i = 0$.
Then, $L = \ell_1$ on $P_1$, thus, the value of $L$ on $P_1$ does not exceed $d$.
In the rest of the proof we will thus assume $k > 1$.


Any linear function reaches its maximum on the polyhedron $P_k$ at one of its vertices. 
We will distinguish several cases of vertices $(\balpha, \bbeta)$ of $P_k \in \mathbb{R}^n \times \mathbb{R}^n$. 
These cases are given by $2n$ equalities and two inequalities among~\eqref{eq:polyhedron_P_k}.

To make our classification more transparent, we will structure it according to the number of equalities on $\alpha_i, \beta_i$. 


Consider the case when we have $2n - 2$ equalities on $\alpha_i, \beta_i$. Then we have three classes of vertices: 
The strict inequalities among~\eqref{eq:polyhedron_P_k} only occur 

\begin{enumerate}[label = (A\arabic*)]
    \item For $\beta_j \geqslant 0$ and $\beta_i \geqslant 0$ for some $1 \leqslant i < j \leqslant n$. 
    Then, from $\ell_2(\balpha) = k-1 = 0$, we find $k = 1$.

    \item\label{vertex:ab} For $\alpha_i \geqslant 0$ and $\beta_j \geqslant 0$ for some $1 \leqslant i, j \leqslant n$. 
    Then, from $\ell_1(\balpha, \bbeta) = d + (k-1)(D - 1)$ and $\ell_2(\balpha) = k - 1$, 
    we find $\alpha_i = \dfrac{k-1}{i} \text{ and } \beta_j = d - \dfrac{k-1}{i}.$ Hence $L(\balpha, \bbeta) = d + \dfrac{k-1}{i}(\omega_{i} - 1)$.

    \item\label{vertex:aa} For $\alpha_i \geqslant 0$ and $\alpha_j \geqslant 0$ for some $1 \leqslant i < j \leqslant n$. Then,
     since $\ell_1(\balpha, \bbeta) = d + (k-1)(D - 1)$ and $\ell_2(\balpha) = k - 1$, the points of this type lie on the hyperplane, defined by $\alpha_i + \alpha_j = d$. 
    Then this point is a convex combination of $\frac{k - 1}{i}\mathbf{e}_i$ and $\frac{k - 1}{j}\mathbf{e}_j$, where $\mathbf{e}_i$ and $\mathbf{e}_j$ are the $i$-th and $j$-th basis vectors in $\mathbb{R}^{2n}$, respectively.
    These points, in turn lie on the lines between the origin and the vertices of type~\ref{vertex:ab}.
    Therefore, points of this class are not vertices of $P_k$.
\end{enumerate}


Consider the case when we have $2n - 1$ equalities on $\alpha_i, \beta_i$. Then there are four classes of vertices:
The strict inequalities only occur 
\begin{enumerate}[label = (B\arabic*)]
    \item For $\ell_1(\balpha, \bbeta) \leqslant d + (k-1)(D - 1)$ and $\beta_j \geqslant 0$ for some $1 \leqslant j \leqslant n$. 
    Then $\beta_j$ is the only nonzero coordinate and, from $\ell_2(\balpha) = k-1$, we find $k=1$.  

    \item\label{vertex:l2b} For $\ell_2(\balpha) \leqslant k - 1$ and $\beta_j \geqslant 0$ for some $1 \leqslant j \leqslant n$.
    Then $\beta_j$ is the only nonzero coordinate and, from $\ell_1(\balpha, \bbeta) = d + (k - 1)(D - 1)$, we find $\beta_j = d + (k - 1)(D - 1)$. 
    Then $L(\balpha, \bbeta) = d + (k-1)(D - 1)$.

    \item\label{vertex:l1a}For $\ell_1(\balpha, \bbeta) \leqslant d + (k-1)(D - 1)$ and $\alpha_i \geqslant 0$ for some $1 \leqslant i \leqslant n$. 
    So $\alpha_i  \leqslant \frac{d + (k-1)(D - 1)}{i D - i+ 1} \leqslant \frac{k-1}{i} + \frac{d}{i(D - 1)}$. 
    Since $\alpha_i$ is the only nonzero coordinate and, then from $\ell_2(\balpha) = k - 1$, we obtain $\alpha_i = \frac{k-1}{i}$. 
    Then any point of this type belongs to a line between the origin and one of the vertices of type~\ref{vertex:ab}. 
    Therefore, points of this class are not vertices of $P_k$.


    \item\label{vertex:l2a} For $\ell_2(\balpha) \leqslant k - 1$ and $\alpha_i \geqslant 0$ for some $1 \leqslant i \leqslant n$. Then $\alpha_i \leqslant \frac{k-1}{i}$, so a point of this type lies on the line between the origin and a vertex of type \ref{vertex:ab}. so it is not a vertex. 
\end{enumerate}

Finally, if we have $2n$ equalities on $\alpha_i, \beta_i$, so $\alpha_i = \beta_i = 0$ for every $i$, then the corresponding vertex is the origin and $L(\balpha, \bbeta) = 0$. 

In summary, we obtain that the linear function $L$ reaches its maximum on the polyhedron $P_k$ at vertices of types~\ref{vertex:ab} and~\ref{vertex:l2b} and
     \[
    \max_{(\balpha, \bbeta) \in P_k} L(\balpha, \bbeta) = \max \biggl(d + (k-1)(D - 1), \max_{ 1 \leqslant j < k} \bigl(d + \dfrac{k-1}{j} (\omega_j - 1) \bigr) \biggr).
    \]
This concludes the proof of our claim.
\end{proof}

\begin{proof}[Proof of Theorem~\ref{theorem_general}]
Let us denote by $\mu$ the order of the minimal polynomial $f_{\min}$. We first recall that $\mu \leqslant n$ by~\cite[Theorem~3.16 and Corollary~3.21]{hong2020global}. 

By Lemma~\ref{lem:ideal_is_wanted}, we get
\[
\ideal{x'_1 - h_1, \ldots, x_1^{(\mu)} - h_{\mu}} \cap \mathbb{K}[x_1^{(\leqslant \mu)}] = I_{\bg} \cap \mathbb{K}[x_1^{(\leqslant\mu)}].
\]
Since $I_{\bg} \cap \mathbb{K}[x_1^{(\leqslant \mu)}] = \ideal{f_{\min}}$, the ideal $\ideal{x'_1 - h_1, \ldots, x_1^{(\mu)} - h_{\mu}} \cap \mathbb{K}[x_1^{(\leqslant \mu)}] = \ideal{f_{\min}}$ is prime and principal. 

Let $1 \leqslant k \leqslant \mu$.
For monomials $m(\balpha, \bbeta) \in h_k$ Corollary~\ref{cor:polyhedron} implies the following inequalities
\begin{equation*} 
            \begin{split}
                 \ell_1(\balpha, \bbeta) & \leqslant d + (k-1)(D - 1), \\
                 \ell_2(\balpha) & \leqslant k - 1,\\
                 \alpha_i, \beta_i & \geqslant 0.
            \end{split}
            \end{equation*}
We denote by $P_k$ the polyhedron defined by these inequalities.

Let us define a homomorphism 
\[
  \varphi \colon \mathbb{K}[\mathbf{x}, x_1', \ldots, x_1^{(\mu)}] \to \mathbb{K}[\mathbf{x}, z_1, \ldots, z_\mu],
\]
such that
\begin{align*}
  x_i & \mapsto  x_i, \\
  x_1^{(i)} & \mapsto p_i(z_i), \; \deg p_i(z_i) = \omega_i.
\end{align*}
Following Lemma \ref{lem:multivariate_square_free} we will chose 
$p_i$ such that $\tilde{f}_{\min}:=\varphi(f_{\min})$ is square-free.
We define $\tilde{f}_k : = \varphi(x_1^{(k)} - h_k)$ for $1 \leqslant k \leqslant \mu$.
Note that $\deg \tilde{f}_k \leqslant \max (\omega_k,  \max\limits_{(\balpha, \bbeta) \in P_k} L(\balpha, \bbeta))$, where $L(\balpha, \bbeta) := \sum_{i=1}^{n} \omega_i \alpha_i + \sum_{i=1}^{n} \beta_i$.
Then by Lemma~\ref{lem:max} we obtain
\[
    \deg \tilde{f}_k \leqslant \max \Biggl(\omega_k,  \max \bigl(d + (k-1)(D - 1), \max_{ 1 \leqslant j < k} (d + \dfrac{k-1}{j} (\omega_j - 1)) \bigr) \Biggr).
\]
Applying Lemma~\ref{lem:total_degree} with $p_i = \tilde{f}_i$ to the principal ideal $\ideal{\tilde{f}_1, \ldots, \tilde{f}_\mu} \cap \mathbb{K}[x_1, z_1, \ldots, z_\mu]$ we obtain $\deg \tilde{f}_{\min}  \leqslant \prod\limits_{i=1}^\mu \deg \tilde{f}_i$.


Applying $\varphi$ to a monomial $m = x_1^{e_0} (x'_1)^{e_1} \ldots (x_1^{(\mu)})^{e_\mu}$ in the support of $f_{\min}$ we obtain
$\varphi(m) = c x_1^{e_0} (z_1^{\omega_1})^{e_1} \ldots (z_\mu^{\omega_\mu})^{e_\mu} + q$ where $c \in \mathbb{K}^\ast$ and $\deg q \leqslant e_0 + \sum_{i=1}^{\mu} \omega_i e_i$.
Together with the obtained degree bound for $\tilde{f}_{\min}$, this gives
\begin{equation}\label{eq:theorem_general_bound_internal}
e_0 + \sum_{i=1}^{\mu} \omega_i e_i \leqslant \prod_{k=1}^\mu \max \biggl( \omega_k, d + (k-1)(D - 1), \max_{ 1 \leqslant j < k} \bigl(d + \dfrac{k-1}{j} (\omega_j - 1) \bigr) \biggr).
\end{equation}
Furthermore, for every monomial  $x_1^{e_0} (x'_1)^{e_1} \ldots (x_1^{(\nu)})^{e_\nu}$ in $f_{\min}$, we have $e_{\mu + 1} = \ldots = e_{\nu} = 0$, so the left-hand side of~\eqref{eq:theorem_general_bound} is equal to the left-hand side of~\eqref{eq:theorem_general_bound_internal}.
The right-hand side of~\eqref{eq:theorem_general_bound} differs from the right-hand side of~\eqref{eq:theorem_general_bound_internal} by extra factors $\geqslant 1$.
Thus, \eqref{eq:theorem_general_bound_internal} implies~\eqref{eq:theorem_general_bound}.
\end{proof}


