\subsection{Proof of Theorem~\ref{theorem_general_specialized}}

\begin{proof}[Proof of Theorem~\ref{theorem_general_specialized}]
    We will deduce the result from Theorem~\ref{theorem_general} through an appropriate choice of the vectors $\bomega \in \mathbb{Z}_{\geqslant 0}^{\nu}$.
    To this end, for $\bomega = \tuple{\omega_1, \ldots, \omega_\nu} \in \mathbb{Z}_{\geqslant 0}^{\nu}$ and $1 \leqslant k \leqslant \nu $, we denote (cf.~\eqref{eq:theorem_general_bound}) 
    \begin{align*}
         m_k(\bomega) & := \max_{ 1 \leqslant j < k} \bigl(d + \frac{k-1}{j} (\omega_j - 1)\bigl),\\
        M_k(\bomega) & := \max \bigl(\omega_k, d + (k-1)(D-1), m_k(\bomega)\bigr).
    \end{align*}       

    \emph{Assume $d \leqslant D$.}
    Take $\bomega$ with
    \[
    \omega_i := d + (i - 1)(D - 1) \text{ for } i = 1, \ldots, \nu.
    \] 
    Let $1 \leqslant k \leqslant \nu$.
    Then, for each $1 \leqslant i < k \leqslant \nu$, we have
    \[
    d + \frac{k-1}{i}(\omega_i - 1) = d + \frac{k-1}{i}(d + (i - 1)(D - 1) - 1) \leqslant d + (k-1)(D - 1),
    \]
    so $m_k(\bomega) \leqslant d + (k-1)(D - 1)$ and $M_k(\bomega) = d + (k-1)(D-1)$. Applying Theorem~\ref{theorem_general} to $\bomega$ we obtain the inequality \eqref{eq:bound_1}.

    \emph{Assume $d > D$.}
    Fix $0 \leqslant \ell < \nu$ and take $\bomega$ such that  
    \begin{align*}
              \omega_i & := i ( D - 1 ) + 1 \text{ for } i = 1,\ldots,\ell, \\ 
              \omega_i & := (i - \ell)(d - 1) + \ell (D - 1) + 1 \text{ for } i = \ell + 1, \ldots, \nu.
    \end{align*}  
    Let $1 \leqslant k \leqslant \ell$. Then
    \[
     d + \dfrac{k-1}{i}(\omega_i - 1) = d + (k - 1)(D - 1) = m_k(\bomega),
    \]
    and  
    \[
    d + (k-1)(D-1) > (D-1) + 1 + (k-1)(D-1) = k(D-1) + 1 = \omega_k.
    \]
    Thus, we obtain
    \[
    M_k(\bomega) = d + (k-1)(D-1) \text{ for } k = 1, \ldots, \ell.
    \]


    Assume now that $\ell + 1 \leqslant k \leqslant \nu$. 
    Then we have
    \[
    d + \frac{k-1}{j}(\omega_j - 1) = d + \frac{k-1}{j} \bigl( (j-\ell)(d - 1) + \ell (D -1) \bigr) > d + (k-1)(D - 1).
    \]
    For $\ell+1 \leqslant i \leqslant j < k$ we have
    \[
    \frac{\omega_i - 1}{i} = \frac{i (d - 1) - \ell (d - D)}{i} \leqslant \frac{j (d - 1) - \ell (d - D)}{j} = \frac{\omega_j - 1}{j}.
    \]
    Hence $m_k(\bomega)= d + \omega_{k-1} - 1 = \omega_k$ and
    \[
    M_k(\bomega) = (k - \ell)(d - 1) + \ell (D-1) + 1.
    \]
    We apply Theorem~\ref{theorem_general} to the constructed vector $\bomega$, and obtain the $\ell$-th inequality in~\eqref{eq:bound_2}.
\end{proof}


