\subsection{Auxiliary statement about Vandermonde type systems}\label{sec:vandermonde}

In this section, we will prove a lemma which will be used in the next section to analyze the solutions at infinity of the polynomial systems obtained by taking Lie derivatives.
Throughout the section we will fix the field of Laurent series $\KK((\bz)) = \KK((z_1))((z_2))\ldots((z_n))$ with the lexicographic monomial ordering with
    \[
        z_n > z_{n-1} > \ldots > z_1.
    \] 

\begin{lemma} \label{lem::Puiseux}
    Let $n, d, D$ be positive integers and $\bgamma \in \mathbb{Z}_{\geqslant 0}^{n}$ such that $ \gamma_1 < \ldots < \gamma_n $.
    For $\balpha$ in $\overline{\KK}^n$ consider the square system:
    \begin{equation} \label{eq::Zariski_new}
         \begin{cases}
             \alpha_1^{\gamma_1} x_1^{d + \gamma_1(D-1)} + \cdots +  \alpha_n^{\gamma_1} x_n^{d + \gamma_1(D-1)} = 0,\\
             \vdots\\
            \alpha_1^{\gamma_{n}} x_1^{d + \gamma_{n}(D-1)} + \cdots   + \alpha_n^{\gamma_{n}} x_n^{d + \gamma_{n}(D-1)}  = 0.\\
         \end{cases}
     \end{equation}
     Then there exists a non-empty Zariski open subset $U \subset \overline{\KK}^n$ such that for every choice $\balpha \in U$ the system \eqref{eq::Zariski_new} has no nonzero solutions in $\overline{\KK}^n$.
\end{lemma}

The idea of the shorter proof given below was proposed to us by Joris van der Hoeven.

\begin{proof} 
    We will prove the statement of Lemma \ref{lem::Puiseux} for the field $\overline{\KK((\bz))}^n$ instead of $\overline{\KK}^n$ and then demonstrate the transition to the original formulation.
    The proof begins with constructing $\balpha \in \overline{\KK((\bz))}^n$ such the system \eqref{eq::Zariski_new} has no nonzero solutions in $\overline{\KK((\bz))}^n$. Next, we establish the existence of an open set $U \subset \overline{\KK((\bz))}^n$ such that for all $\balpha \in U$ the system \eqref{eq::Zariski_new} has no nonzero solutions. Finally, we demonstrate the transition to the original statement of the lemma.


    \emph{Step 1.} Consider $\balpha^\ast = \tuple{z_1, \ldots, z_n}$. 
    We show that for $\balpha^\ast$ the system \eqref{eq::Zariski_new} has no nonzero solutions in $\overline{\KK((\bz))}^n$ via induction on $n$. For the base case of induction at $n=1$ the system \eqref{eq::Zariski_new} takes the shape
    \begin{equation} \label{eq::Zariski_basecase}
            \alpha_1^{\gamma_1} x_1^{d + \gamma_1(D-1)} = 0.
    \end{equation}
    Note that for every $\alpha_1 \neq 0$, equation \eqref{eq::Zariski_basecase} has no nonzero solutions in $\overline{\KK((z_1))}$, so as for $\alpha_1 = z_1$.

    Now consider the system \eqref{eq::Zariski_new} for $n > 1$.
    Assume for contradiction that the system \eqref{eq::Zariski_new} has a nonzero solution $\tuple{x_1^\ast,\ldots, x_n^\ast}$ in $\overline{\KK((\bz))}^n$. 
    If $x_n^\ast = 0$, then the square system of the first $n-1$ equations of the system \eqref{eq::Zariski_new} has no nonzero solutions with $\balpha = \tuple{z_1, \ldots, z_{n-1}}$ by the induction hypothesis.  

    If $x_n^\ast \neq 0$, then we dehomogenize the system \eqref{eq::Zariski_new} with respect to $x_n$ (i.e., set $\tilde{x}_i = \frac{x_i^\ast}{x_n^\ast}$):
    \begin{equation} \label{eq::Zariski_dehomogenized}
         \begin{cases}
             z_1^{\gamma_1}\tilde{x}_1^{d+\gamma_1(D-1)} + \cdots + z_{n-1}^{\gamma_1}\tilde{x}_{n-1}^{d+\gamma_1(D-1)} + z_n^{\gamma_1} = 0,\\
             \vdots\\
            z_1^{\gamma_n} \tilde{x}_1^{d + \gamma_n(D-1)} + \cdots   + z_{n-1}^{\gamma_n} \tilde{x}_{n-1}^{d + \gamma_n(D-1)} + z_n^{\gamma_n}  = 0.\\
         \end{cases}
     \end{equation}

    Let $a$ be the minimum of orders of $\tilde{x}_i$ in $z_n$. For every $1 \leqslant i \leqslant n-1$ we express $\tilde{x}_i$ as a Puiseux series in $z_n$ with coefficients in $\overline{\KK((z_1))\ldots((z_{n-1}))}$
    \begin{equation} \label{eq::Zariski_substitution}
        \tilde{x}_i = \theta_i z_n^a + p_i(z_n),
    \end{equation}
    where $\theta_i \in \overline{\KK((z_1))\ldots((z_{n-1}))}$ and $p_i(z_n)$ is a Puiseux series in $z_n$ with coefficients in $\overline{\KK((z_1))\ldots((z_{n-1}))}$ such that $\deg p_i(z_n) > a$.
    Note that by the construction $\theta_i \neq 0$ for some $1 \leqslant i \leqslant n-1$.

    We substitute \eqref{eq::Zariski_substitution} to the system \eqref{eq::Zariski_dehomogenized}  and consider the lowest terms of the equations.
    Assume $a(d + \gamma_1(D-1)) > \gamma_1$. Then the lowest term of the first equation is $z_n^{\gamma_1}$ and it does not cancel. So we do not have the first equality.
    Thus, we can further assume that $a(d + \gamma_1(D-1)) \leqslant \gamma_1$. 
    Since $a \leqslant \frac{\gamma_1}{d + \gamma_1(D-1)}$ and $\gamma_i = \gamma_1 + N_i$ for some $N_i \in \mathbb{Z}_{>0}$ for every $2 \leqslant i \leqslant n$, we have 
    \[
        a(d + \gamma_i(D-1)) \leqslant \frac{\gamma_1( d + \gamma_i(D-1)}{d + \gamma_1(D-1))} = \gamma_1(1 + \frac{N_i(D-1)}{d + \gamma_1 (D-1)}) < \gamma_i.
    \]
    Thus, for the coefficients for the lowest terms of the last $n-1$ equations of the system \eqref{eq::Zariski_substitution} we have
    \begin{equation*}
        \begin{cases}
            z_1^{{\gamma}_2} \theta_1^{d + {\gamma}_2(D-1)} + \cdots + z_{n-1}^{{\gamma}_2} \theta_{n-1}^{d + {\gamma}_2(D-1)} = 0, \\
            \vdots \\
            z_1^{{\gamma}_{n}} \theta_1^{d + {\gamma}_{n}(D-1)} + \cdots + z_{n-1}^{{\gamma}_{n}} \theta_{n-1}^{d + {\gamma}_{n}(D-1)} = 0. \\
        \end{cases}
    \end{equation*}
    This system as a system in variables $\theta_1, \ldots, \theta_n$ has no nonzero solutions by the induction hypothesis, and so we get a contradiction with $\theta_i \neq 0$ for some $1 \leqslant i \leqslant n-1$. This finishes the first step of the proof.


    Since the substitution $\tuple{z_1, \ldots, z_n} \rightarrow \tuple{s_1 z_1, \ldots, s_n z_n}$, $s_i \in \mathbb{Z} \setminus \{ 0 \}$ to the system \eqref{eq::Zariski_new} does not change the lowest terms of equations \eqref{eq::Zariski_dehomogenized} in $z_n$, with the same argument as for $\balpha^\ast$ we can show that for $\balpha = \tuple{s_1 z_1, \ldots, s_n z_n}$ the system \eqref{eq::Zariski_new} has no nonzero solutions in $\overline{\KK((\bz))}^n$.



    \emph{Step 2.} 
    Consider the first-order formula in the language of fields 
    \[
        \Phi(\balpha) := \forall \bx \bigl((\bx \text{ is a solution of \eqref{eq::Zariski_new} with coefficients $\balpha$} ) \Rightarrow (x_1 = 0 \vee \ldots \vee x_n=0) \bigr)
    \]
    and let $E_0$ be the set $\{ \balpha \in \overline{\KK}^n \; | \; \Phi(\balpha)\}$.
    The set $E_0$ is constructible, so $E_0$ is contained in some proper Zariski closed subset or $E_0$ contains a nonempty Zariski open set \cite[Ch.~II, §~3, Ex.~3.18(b)]{hartshorne1977graduate}.

    Assume that $E_0$ is contained in some proper Zariski closed set defined by the polynomial $p(\balpha)$ over $\overline{\KK}$. Then the formula
    \begin{equation} \label{eq::formula}
        \forall \balpha \bigl(\Phi(\balpha) \Rightarrow (p(\balpha) = 0)\bigr)
    \end{equation}
    is true over $\overline{\KK}$. Since $\overline{\KK}$ and $\overline{\KK((\bz))}$ are elementary equivalent as algebraic closed fields of zero characteristic \cite[Th.~1.4, Th.~1.6]{marker2017model}, formula \eqref{eq::formula} is true over $\overline{\KK((\bz))}$. 
    On the other hand, as shown in Step 1, the set $E_1 := \{ \balpha \in \overline{\KK((\bz))}^n \; | \; \Phi(\balpha) \}$ contains a Zariski dense set $\{(s_1 z_1, \ldots, s_n z_n) \mid s_i \in \mathbb{Z} \setminus \{ 0\}\}$. 
    This leads to a contradiction with the assumption that $E_0$ was contained in a proper Zariski closed set.


    Thus, $E_0$ contains a nonempty Zariski open subset $U$, such that for every choice $\balpha \in U \subset \overline{\KK}^n$ the system \eqref{eq::Zariski_new} has no nonzero solutions in $\overline{\KK}^n$. This concludes the proof.
\end{proof}



\subsection{Proof of Theorem~\ref{thm:sharp}}\label{sec:proof_general_sharp}

\begin{notation}\label{not:lower_bound}
For this section, we will fix positive integers $d, D, n$ satisfying $d \leqslant D$.
For a tuple $\balpha = \tuple{\alpha_2, \ldots, \alpha_n} \in \KK^{n - 1}$, we consider an ODE system $\bx' = \bg_{\balpha}(\bx)$:
\begin{equation}\label{eq:sigma}
\begin{cases}
    x_1' = x_1^{d} + (x_2 + 1)^{d} + \cdots + (x_n + 1)^d,\\
    x_2' = \alpha_2 x_2^D,\\
    \vdots\\
    x_n' = \alpha_n x_n^D.
\end{cases}
\end{equation}
That is, $g_{\balpha, 1} = x_1^{d} + (x_2 + 1)^{d} + \cdots + (x_n + 1)^d$ and $g_{\balpha, i} = \alpha_i x_i^D$ for $2 \leqslant i \leqslant n$.

We also denote (see Notation~\ref{not:proofs_notation})
\begin{equation}\label{eq:pi}
  p_{\balpha, i} := x_1^{(i)} - \mathcal{L}_{\bg_{\balpha}}^{i - 1}( g_1 ) \quad\text{ for }1 \leqslant i \leqslant n.
\end{equation}
We further denote $I_{\balpha} := \ideal{p_{\balpha, 1}, \ldots, p_{\balpha, n}} \subseteq \mathbb{K}[x_1, \ldots, x_1^{(n)}, x_2, \ldots, x_n]$. 
Finally, we introduce the following fields of rational functions
\begin{equation}\label{eq:field}
F_\ell := \KK(x_1, \ldots, x_1^{(\ell - 1)}, x_1^{(\ell + 1)}, \ldots, x_1^{(n)}) \quad \text{ where }\quad 0 \leqslant \ell \leqslant n.
\end{equation}
A polynomial which reaches the bound given in Theorem~\ref{theorem_general_specialized}, by formula~\eqref{eq:bound_1}, must have the following degrees in $x_1, x_1', \ldots, x_1^{(n)}$: 
\[
N_0 := \prod\limits_{k = 1}^n (d + (k - 1)(D - 1)), \quad N_\ell := \frac{N_0}{d + (\ell - 1)(D - 1)} \text{ for } i = 1, \ldots, n.
\]

\end{notation}

\begin{lemma}\label{lem:sharp_radical}
    For every $0 \leqslant \ell \leqslant n $, the ideal generated by $p_{\balpha, 1}, \ldots, p_{\balpha, n}$ in $F_\ell[x_1^{(\ell)}, x_2, x_3, \ldots, x_n]$ is radical.
\end{lemma}


\begin{proof}  
    We fix a monomial ordering on $\KK[x_1^{(\leqslant n)}, x_2, \ldots, x_n]$ to be the lexicographic monomial ordering with 
    \[
    x_1^{(n)} > x_1^{(n-1)} > \ldots > x'_1 > x_1 > x_2 > \ldots > x_n.
    \]
    The leading term of $p_{\balpha, i}$ is $x_1^{(i)}$.
    Therefore, the leading terms of all generators of $I_{\balpha}$ are distinct variables. 
    Hence this set is a Gr\"obner basis of $I_{\balpha}$
    by the Buchberger's first criterion. 
    Then $\KK[x_1^{(\leqslant n)}, x_2, \ldots, x_n] / I_{\balpha} \simeq \mathbb{K}[\mathbf{x}]$ and the ideal $I_{\balpha}$ is prime and, thus, radical. 
    By \cite[Proposition 3.11]{atiyah2018introduction} the ideal generated by $I_{\balpha}$ in the localization $F_\ell[x_1^{(\ell)}, x_2, x_3, \ldots, x_n]$ will be radical.
\end{proof}

\begin{corollary} \label{cor::sharp_radical}
   For every $0 \leqslant \ell \leqslant n $, the ideal generated by $p_{\balpha, 1}, \ldots, p_{\balpha, \ell - 1},  p_{\balpha, \ell + 1}, \ldots, p_{\balpha, n}$ in $F_\ell[x_2, x_3, \ldots, x_n]$ is radical. 
\end{corollary}

\begin{proof}
    Let $J = \ideal{p_{\balpha, 1}, \ldots, p_{\balpha, \ell - 1},  p_{\balpha, \ell + 1}, \ldots, p_{\balpha, n}} \subset F_\ell[x_2, \ldots, x_n]$.
    Since $p_{\balpha, \ell}$ is linear in $x_1^{(\ell)}$, we have $J = I_{\balpha} \cap F_\ell[x_2, x_3, \ldots, x_n]$.
    Then Lemma~\ref{lem:sharp_radical} implies that $J$ is radical.
\end{proof}

\begin{lemma} \label{lem::jacobi}
    If all the coordinates of $\balpha$ are nonzero, then for every $0 \leqslant \ell \leqslant n$, the images of $\{ x_1, x_1', \ldots, x_1^{(\ell - 1)}, x_1^{(\ell + 1)}, \ldots, x_1^{(n)} \}$ are algebraically independent in $\mathbb{K}[x_1^{(\leqslant n)}, x_2, \ldots, x_n]/I_{\balpha} \cong \mathbb{K}[\mathbf{x}]$.
\end{lemma}
\begin{proof}
    Denote $R:=\mathbb{K}[x_1^{(\leqslant n)}, x_2, \ldots, x_n]/I_{\balpha}$.
    We will denote the images of $x_1^{(\leqslant n)}, x_2, \ldots, x_n$ in $R$ by the same letters.
    We have the following equalities modulo $I_{\balpha}$:
    \[
      x_1^{(i)} = \mathcal{L}_{\bg_{\balpha}}^i(x_1) =: h_i(\bx), \quad \text{ for } 0 \leqslant i \leqslant n.
    \]
    Let $J$ be the Jacobian determinant of $h_0, \ldots,h_{\ell - 1}, h_{\ell + 1}, \ldots,  h_n$  with respect to $\mathbf{x}$.
    Since $h_0 = x_1$, the determinant $J$ is equal to the Jacobian of $h_1, \ldots,h_{\ell - 1}, h_{\ell + 1}, \ldots,  h_n$ with respect to $x_2, \ldots, x_n$.

    Consider the matrix consisting of the leading terms of each entry of this Jacobian with respect to the degree lexicographic ordering with
    \[
        x_2 > x_3 > \cdots > x_n.
    \]
    Since 
    \[
    \lt\left( \frac{\partial h_i}{\partial x_j} \right) = c_i \alpha_j^{i - 1} x_j^{d + (D - 1)(i - 1) - 1},\quad \text{ for } 1 \leqslant i \leqslant n, \; 2 \leqslant j \leqslant n,
    \]
    where $c_i =  d \prod_{j = 1}^{i - 1} \bigl(d + j (D - 1)\bigr)$, the corresponding determinant of the leading terms is equal to
    \begin{equation*} 
     J_{\lt} = \begin{vmatrix}  
       c_1 x_2 ^{d-1} &\ldots & c_1 x_n ^{d-1} \\
        c_2 \alpha_2 x_2^{d + (D-1) -1 } & \ldots &  c_2 \alpha_n  x_n^{d + (D-1) -1 } \\
         \vdots & \ddots & \vdots \\
         c_{\ell - 1} \alpha_2^{\ell - 2} x_2^{d + (\ell - 1)(D - 1) - 1} &\ldots &  c_{\ell - 1} \alpha_n^{\ell - 2} x_n^{d + (\ell - 1)(D - 1) - 1}\\  
         c_{\ell + 1} \alpha_2^{\ell } x_2^{d + (\ell + 1)(D - 1) - 1} &\ldots &  c_{\ell + 1} \alpha_n^{\ell } x_n^{d + (\ell + 1)(D - 1) - 1}\\
         \vdots & \ddots & \vdots \\
          c_n \alpha_2^{n - 2} x_2^{d + (n - 1)(D - 1) - 1} &\ldots &  c_n \alpha_n^{n - 2} x_n^{d + (n - 1)(D - 1) - 1}\\
        \end{vmatrix}.
       \end{equation*}
       The leading term of the determinant $J_{\lt}$ is the product over the antidiagonal 
       \[
        c x_2^{d + (n - 1)(D - 1)- 1} x_3^{d + (n - 2)(D - 1)- 1} \ldots  x_{\ell}^{d + (\ell + 1) (D - 1) - 1} x_{\ell + 1}^{d + (\ell - 1) (D - 1) - 1} \ldots x_n^{d-1}
       \]
       for a nonzero constant $c$. 
       Since $\lt(J_{\lt}) \neq 0$, we have $\lt(J) = \lt(J_{\lt}) \neq 0$.
       The claimed algebraic independence then follows from the Jacobian criterion \cite[Theorem~2.2]{ehrenborg1993apolarity}.
\end{proof}

\begin{lemma}\label{lem:sharp:count}
    Following Notation \ref{not:lower_bound}, consider the system of equations
    \begin{equation} \label{eq::number_of_solutions_zero}
        p_{\balpha, 1} = \cdots = p_{\balpha, n} = 0.
    \end{equation}
    Then there exists a non-empty Zariski open subset $U\subset \mathbb{K}^{n-1}$ such that, for every $\balpha\in U$ and every $0 \leqslant \ell \leqslant n$, the system \eqref{eq::number_of_solutions_zero} has exactly $N_{\ell}$ distinct solutions in $\overline{F}_\ell$, the algebraic closure~of~$F_\ell$.
 \end{lemma}

We first prove an auxiliary lemma which we will use to rewrite the system~\eqref{eq::number_of_solutions_zero}.

\begin{lemma} \label{lem::diff_operator}
 Let $R$ be a differential $\mathbb{K}$-algebra and let $\mathcal{D}$ be a differential operator $\mathcal{D} : R \rightarrow R$.
   Fix $k\in \mathbb{Z}_{>0}$ and $b\in R$. 
   Assume that for some $a \in R$ we have $\mathcal{D}(a) = a^k + b$.
   Then the following equality of ideals in $R$ holds for every $n \geqslant 1$
\[
    \ideal{\mathcal{D}(a), \mathcal{D}^2(a), \ldots, \mathcal{D}^n(a)}  = \ideal{\mathcal{D}(a), \mathcal{D}(b), \mathcal{D}^2(b), \ldots, \mathcal{D}^{n-1}(b)}.
\]
\end{lemma}

\begin{proof}
    We will prove the equality of ideals by showing the inclusions in both directions.

    We prove the inclusion $\ideal{\mathcal{D}(a), \mathcal{D}^2(a), \ldots, \mathcal{D}^n(a)}  \subset \ideal{\mathcal{D}(a), \mathcal{D}(b), \mathcal{D}^2(b), \ldots, \mathcal{D}^{n-1}(b)}$  through induction on $n$, starting with $n = 1$, when $\ideal{\mathcal{D}(a)} \subset \ideal{ \mathcal{D}(a)}$.

    Now we consider the case $n > 1$. Since  
    by the induction hypothesis 
    \[
        \mathcal{D}^{n - 1}(a) \in \ideal{\mathcal{D}(a), \mathcal{D}(b), \ldots, \mathcal{D}^{n-2}(b)},
    \]
    then
    \[
        \mathcal{D}^{n}(a) \in \ideal{\mathcal{D}(a), \mathcal{D}^2(a), \mathcal{D}(b), \ldots, \mathcal{D}^{n - 1}(b)}.
    \]
    Since $\mathcal{D}^2(a) \in \ideal{\mathcal{D}(a), \mathcal{D}(b)}$, we have 
    \[
        \mathcal{D}^{n}(a) \in \ideal{\mathcal{D}(a), \mathcal{D}(b), \ldots, \mathcal{D}^{n - 1}(b)}. %.\qedhere
    \]

    Now we prove the inclusion $\ideal{\mathcal{D}(a), \mathcal{D}^2(a), \ldots, \mathcal{D}^n(a)}  \supset \ideal{\mathcal{D}(a), \mathcal{D}(b), \mathcal{D}^2(b), \ldots, \mathcal{D}^{n-1}(b)}$ through induction on $n$. For the base case $n = 1$ we have $\ideal{\mathcal{D}(a)} \supset \ideal{\mathcal{D}(a)}$. 
    Consider the case $n > 1$. Since by the induction hypothesis
    \[
    \mathcal{D}^{n-2}(b) \in \ideal{\mathcal{D}(a), \mathcal{D}^2(a), \ldots, \mathcal{D}^{n-1}(a)},
    \]
    we have 
    \[
    \mathcal{D}^{n-1}(b) \in \ideal{\mathcal{D}(a), \mathcal{D}^2(a), \ldots, \mathcal{D}^{n}(a)} .\qedhere
    \]

\end{proof}

\begin{proof}[Proof of Lemma~\ref{lem:sharp:count}]
    First of all we note that for every $1 \leqslant \ell \leqslant n$ the solutions of the system 
         \begin{equation} \label{eq::number_of_solutions_short}
         p_{\balpha, 1} = \cdots = p_{\balpha, \ell-1} = p_{\balpha, \ell+1} = \cdots = p_{\balpha, n} = 0     
         \end{equation} 
    in the variables $x_2, \ldots, x_n$ can be uniquely lifted to solutions of the system \eqref{eq::number_of_solutions_zero} in the variables $x_1^{(\ell)}, x_2, \ldots, x_n$ by substituting these solutions of \eqref{eq::number_of_solutions_short} to $p_{\balpha, \ell} = x_1^{(\ell)} - \mathcal{L}_{\bg_{\balpha}}^{\ell}(g_{\balpha, 1}) = 0$. 
    Thus, the number of solutions of the system \eqref{eq::number_of_solutions_zero} for the case $1 \leqslant \ell \leqslant n$ is equal to the number of solutions of the system \eqref{eq::number_of_solutions_short}.

     \emph{Step 1: Zero-dimensionality.}
     Since $\mathbb{K}[x_1, \ldots, x_1^{(n)}, x_2, \ldots, x_n] / I_{\balpha} \simeq \mathbb{K}[\mathbf{x}]$, $I_{\balpha}$ is of dimension $n$. 
     Let $U_{-1} = (\KK \setminus \{ 0\})^{n-1} \subset \KK^{n-1}$ be a non-empty Zariski open set of all vectors without zero components. 
     For every $0 \leqslant \ell \leqslant n$ and $\balpha \in U_{-1}$ the set $x_1, \ldots, x_1^{(\ell - 1)}, x_1^{(\ell + 1)}, \ldots, x_1^{(n)}$ is algebraically independent modulo $I_{\balpha}$ by Lemma~\ref{lem::jacobi}.
     Since $\dim(I_{\balpha})=n$, it is a maximal algebraically independent set. 
     Thus, $I_{\balpha}\cdot F_{\ell}[x_1^{(\ell)}, x_2, \ldots, x_n]$ is a zero-dimensional ideal.

      Now for every $1 \leqslant \ell \leqslant n$ consider the ideal $J_\ell$ generated by $ p_{\balpha, 1}, \ldots, p_{\balpha, \ell-1}, p_{\balpha, \ell+1}, \ldots, p_{\balpha, n}$ in $\mathbb{K}[x_1, \ldots, x_1^{(\ell - 1)}, x_1^{(\ell + 1)}, \ldots, x_1^{(n)}, x_2, \ldots, x_n]$. 
      Since, among $p_{\balpha, 1}, \ldots,  p_{\balpha, n}$, only $p_{\balpha, \ell}$ involves the variable $x_1^{(\ell)}$ (and is linear in it), we have 
      \[
      I_{\balpha} \cap F_{\ell}[x_2, \ldots, x_n] = J_\ell \cdot F_{\ell}[x_2, \ldots, x_n].
      \]
      In particular, $\dim(J_\ell \cdot F_{\ell}[x_2, \ldots, x_n]) = 0$.

     \emph{Step 2: Solutions at infinity.}
     Consider the homogenizations $p_{\balpha, 1}^h, \ldots, p_{\balpha, n}^h$ of $p_{\balpha, 1}, \ldots, p_{\balpha, n}$ considered as polynomials in $x_1^{(\ell)}, x_2, \ldots, x_n$ using
     an additional variable $h$.

     For every $0 \leqslant \ell \leqslant n$, we will produce an nonempty Zariski open set $U_\ell \subset \KK^{n - 1}$ such that, for every $0 \leqslant \ell \leqslant n$ and for every $\balpha \in U_\ell$, the following system does not have a solution in $\overline{F}_\ell$ at infinity (that is, in $\mathbb{V}(h)$):
     \begin{itemize}
         \item if $\ell = 0$, then the system is $p_{\balpha, 1}^h = \cdots = p_{\balpha,n}^h = 0$ in variables $\bx, h$;
         \item if $1 \leqslant \ell \leqslant n$, then the system is $p_{\balpha, 1}^h = \cdots = p_{\balpha, \ell - 1}^h = p_{\balpha, \ell + 1}^h = \cdots = p_{\balpha,n}^h = 0$ in variables $x_2, \ldots, x_n, h$.
     \end{itemize}


     \emph{Assume that $d < D$.} 
     For $d < D$, the points at infinity for the case $\ell = 0$
     are given by the solutions (in projective space) of the equations $p_{\balpha,1}^h = \cdots = p_{\balpha,n}^h = h =0$. Here 
     \begin{equation} \label{eq::initial_condition}
         \begin{cases}
             p_{\balpha,1}^h|_{h=0} = x_1^d + x_2^d + \cdots + x_n^{d} = 0,\\
             p_{\balpha,2}^h|_{h=0} = c_1 ( \alpha_2 x_2^{d + D - 1} + \cdots + \alpha_n x_n^{d + D - 1}) = 0, \\
             \vdots\\
             p_{\balpha,n}^h|_{h=0} = c_n ( \alpha_2^{n-1} x_2^{d + (n-1)(D-1)} + \cdots +  \alpha_n^{n-1} x_n^{d + (n-1)(D-1)} ) = 0,\\
         \end{cases}
     \end{equation}
     where $c_i = \prod_{k=1}^{i}(d + (k-1)(D-1))$ for every $1 \leqslant i \leqslant n$.
     Note that the solutions of the $n - 1$ last equations of the system \eqref{eq::initial_condition} can be lifted to solutions of the entire system. 
     By applying Lemma~\ref{lem::Puiseux} for the the $n - 1$ last equations of the system \eqref{eq::initial_condition} there exist a non-empty Zariski open subset $U_0 \subset \mathbb{K}^{n-1}$ such that for every choice $\balpha \in U_{0}$ the system \eqref{eq::initial_condition} has no nonzero solutions. 
     Therefore the system $p_{\balpha,1}^h = \ldots = p_{\balpha,n}^h = h =0$ has no nonzero solutions in $\overline{F}_0$ for $\balpha \in U_{0}$.


    For the case $1 \leqslant \ell \leqslant n$ 
    the points at infinity are the solutions of the system obtained from \eqref{eq::initial_condition} by substituting $x_1 = 0$ and omitting the $\ell$-th equation. 
    Then by applying Lemma~\ref{lem::Puiseux} to the resulting system \eqref{eq::initial_condition} there exist a non-empty Zariski open subset $U_{\ell} \subset \mathbb{K}^{n-1}$ such that for every choice $\balpha \in U_{\ell}$ the system \eqref{eq::initial_condition} has no nonzero solutions. 
    Therefore the system $p_{\balpha, 1}^h = \cdots = p_{\balpha, \ell - 1}^h = p_{\balpha, \ell + 1}^h = \cdots = p_{\balpha,n}^h = h = 0$ has no nonzero solutions in $\overline{F}_\ell$ for $\balpha \in U_{\ell}$.


    \emph{Now consider the case $d = D$.} 
    In this case the points at infinity for $\ell= 0$ are also given by the solutions in $\overline{F}_0$ of the equations $p_{\balpha,1}^h|_{h = 0} = \cdots = p_{\balpha,n}^h|_{h = 0} = 0$, where $p_{\balpha,1}^h|_{h = 0} = x_1^D + x_2^D + \cdots + x_n^D$. 
    Consider $p_{\balpha,1}^h|_{h = 0}$ as the image $\mathcal{D}(x_1)$ where $\mathcal{D}$ is defined to be a differential operator $\mathcal{D}\colon \mathbb{K}[\mathbf{x}] \rightarrow \mathbb{K}[\mathbf{x}]$ with 
    \[
      x_i \mapsto  (\mathcal{L}_{\bg_{\balpha}}(x_i))^h|_{h = 0},
    \]
   where $\mathcal{L}_{\bg}$ is the Lie derivative operator (see Notation~\eqref{not:proofs_notation}).
    Then we can rewrite the system $p_{\balpha,1}^h|_{h = 0} = \cdots = p_{\balpha,n}^h|_{h = 0} = h = 0$ as 
    \[
        \mathcal{D}(x_1) =  \mathcal{D}^2(x_1) = \mathcal{D}^3(x_1) = \cdots =  \mathcal{D}^{n}(x_1) = h = 0.
    \]
    By Lemma~\ref{lem::diff_operator} with $a = x_1, k = D$ and $b = x_2^D + \cdots + x_n^D$ this is equivalent to 
    \[
        \mathcal{D}(x_1) = \mathcal{D}(b) = \mathcal{D}^2(b) = \cdots = \mathcal{D}^{n-1}(b) = h = 0, 
    \]
    which itself is equivalent to the system~\eqref{eq::initial_condition} with $d = D$.
    Note that for the case $1 \leqslant \ell \leqslant n$ the points at infinity are given by \eqref{eq::initial_condition} with $d = D$ and $x_1 = 0$ and the $\ell$-th equation omitted. 
    Therefore, the same argument using Lemma \ref{lem::Puiseux} as in the case $d < D$ applies here.


    \emph{Step 3: Computing the B\'ezout bound.}
        Consider a non-empty open set $U := \bigcap\limits_{i=-1}^{n} U_{i} \subset \KK^{n-1}$.
        Thus, for $\ell = 0$ the ideal generated by $p_{\balpha,1}, \ldots, p_{\balpha,n}$ in $F_{\ell}[x_1, x_2, \cdots, x_n]$ is a zero-dimensional radical ideal by Lemma~\ref{lem:sharp_radical} and for every choice $\balpha \in U$ the system $p_{\balpha,1} = \ldots = p_{\balpha,n} = 0$
        has no solutions at infinity, so the number of distinct solutions, counted with multiplicity, of the system \eqref{eq::number_of_solutions_zero} with $\balpha \in U$ is equal to the B\'ezout bound. Therefore, the number of solutions in $\overline{F}_{0}$,  counted with multiplicity, is equal to the product of the total degrees of $p_{\balpha,1}, \ldots, p_{\balpha,n}$ in $\mathbf{x}$ which is equal to $N_{0}$. 

        For every $1 \leqslant \ell \leqslant n$ the ideal generated by $p_{\balpha,1},  \ldots, p_{\balpha, \ell - 1}, p_{\balpha, \ell + 1}, \ldots, p_{\balpha,n}$ is a zero-dimensional radical ideal in $\mathbb{F}_{\ell}[x_2, \ldots, x_n]$ by Corollary~\ref{cor::sharp_radical} and for every choice $\balpha \in U$ the system \eqref{eq::number_of_solutions_short}
        has no solutions at infinity, so the number of distinct solutions,  counted with multiplicity, of the system \eqref{eq::number_of_solutions_short} (considered in the variables $x_2, \ldots, x_n$), 
        as well as the the number of distinct solutions, counted with multiplicity, of the system \eqref{eq::number_of_solutions_zero} (considered in the variables $x_1^{(\ell)}, x_2, \ldots, x_n$),
        is equal to the B\'ezout bound for the system~\eqref{eq::number_of_solutions_short}, which is precisely~$N_{\ell}$.  
\end{proof}


\begin{lemma}\label{lem:distinct}
    Consider $0 \leqslant \ell \leqslant n-1$ and the system $p_{\balpha, 1} = \ldots = p_{\balpha, n} = 0$ (see Notation~\ref{not:lower_bound}) as a polynomial system in variables $x_1^{(\ell)}, x_2, \ldots, x_n$ over $F_\ell$.
    Assume that the coordinates of $\balpha$ are distinct prime numbers larger than $d$.
    Then the $x_1^{(\ell)}$-coordinates of the solutions of the system in $\overline{F}_\ell$ are all distinct.
\end{lemma}

The proof of Lemma~\ref{lem:distinct} will use the concept of \emph{identifiability} from control theory. 
Here we give a specialization of the general analytic definition~\cite[Definiton~2.5]{hong2020global} to the class of systems we consider.
\begin{defin}\label{def:identifiability}
    Let $\bx' = \bg(\bx)$ be a polynomial ODE system, where $\bx = \tuple{x_1, \ldots, x_n}$ and $\bg \in \mathbb{C}[\bx]^n$.
    Then the initial condition $x_i(0)$ is said to be \emph{identifiable} from $x_j$ if there exists an nonempty Zariski open $U \subset \mathbb{C}^n$ such that, for every solution $\mathbf{X}(t)$ of the system analytic at $t = 0$ with $\mathbf{X}(0) \in U$ and any other solution $\widetilde{\mathbf{X}}(t)$ analytic at $t = 0$ the equality $X_j(t) = \widetilde{X}_j(t)$ in a neighbourhood of $t = 0$ implies $X_i(0) = \widetilde{X}_i(0)$.
\end{defin}

The convenience of the notion of identifiability for us is that, while this property can be established by analytic means, it allows to deduce purely algebraic consequences.

\begin{lemma}\label{lem:identifiability_to_algebra}
    In the notation of Definition~\ref{def:identifiability}, if $x_i(0)$ is identifiable from $x_j$, then there exist polynomials $q, r \in \mathbb{C}[x_j^{(\leqslant n)}]$ such that $q\not\in I_{\bg}$ and $q x_i - r \in I_{\bg}$.
\end{lemma}

\begin{proof}
    By~\cite[Proposition~3.4]{hong2020global}, identifiability of $x_i(0)$ from $x_j$ implies that there exist $q, r \in \mathbb{C}[x_j^{(\infty)}]$ such that $q \not\in I_{\bg}$ and $qx_i - r \in I_{\bg}$.
    Let $f$ be the minimal polynomial of the elimination ideal $I_{\bg} \cap \mathbb{C}[x_j^{(\infty)}]$.
    We have $\ord_{x_j}f \leqslant n$ by \cite[Theorem~3.16 and Corollary~3.21]{hong2020global}.
    Therefore, by performing Ritt's reduction~\cite[Section~3.1]{Boulier2} of $qx_i + r$ with respect to $f$, we find $\tilde{q}, \tilde{r} \in \mathbb{C}[x_j^{(\leqslant n)}]$ such that $\tilde{q} \not\in I_{\bg}$ and $\tilde{q}x_i - \tilde{r} \in I_{\bg}$.
\end{proof}

It turns out that our system~\eqref{eq:sigma} does possess this property.

\begin{lemma}\label{lem:identifiability}
    Assume that the coordinates of $\balpha\in \mathbb{Q}^{n - 1}$ are distinct prime numbers greater than $d$.
    Then, in system $\bx' = \bg
_{\balpha}(\bx)$ from~\eqref{eq:sigma}, considered over $\KK = \mathbb{C}$, the initial conditions $x_2(0), \ldots, x_n(0)$ are identifiable from~$x_1$.
\end{lemma}

\begin{proof}
    Due to the symmetry, it is sufficient to prove the identifiability of $x_2(0)$.
    To this end, we first observe that the complex-valued solutions of an equation $x' = \alpha x^D$ with $\alpha \neq 0$ analytic at $t = 0$ are the following:
    \begin{equation}\label{eq:analytic_solution}
    X(t) = \begin{cases}
        X(0) e^\alpha t, \text{ if } D = 1,\\
        (\alpha (1 - D) t + X(0)^{1 - D})^{\frac{1}{1 - D}}, \text{ if } D > 1 \text{ and } x(0) \neq 0,\\
        0, \text{ if } X(0) = 0.
    \end{cases}
    \end{equation}
    In order to verify Definition~\ref{def:identifiability}, we set the open $U \subset \mathbb{C}^n$ to be a set of vectors $\tuple{v_1, \ldots, v_n}$ with nonzero coordinates such that the numbers $\frac{v_2^{1 - D}}{\alpha_2}, \ldots, \frac{v_n^{1 - D}}{\alpha_n}$ are pairwise distinct.
    Consider any solutions $\bX(t)$ and $\widetilde{\bX}(t)$ of $\Sigma$ in the ring of $\mathbb{C}$-valued functions locally analytic at $t = 0$ such that $\bX(0) \in U$ and $X_1(t) = \widetilde{X}_1(t)$ in a neighbourhood of $t  = 0$.
    Then we have $X_1'(t) - X_1(t)^d = \widetilde{X}_1'(t) - \widetilde{X}_1(t)^d$, so
    \begin{equation}\label{eq:equalityX_Xt}
    (X_2(t) + 1)^d + \ldots + (X_n(t) + 1)^d = (\widetilde{X}_2(t) + 1)^d + \ldots + (\widetilde{X}_n(t) + 1)^d.
    \end{equation}
    We denote $F(t) := (X_2(t) + 1)^d + \ldots + (X_n(t) + 1)^d$ and consider the cases $D = 1$ and $D > 1$ separately.

    \emph{Case $D = 1$.} Then $F(t)$ is a linear combination of exponential functions. 
    Since $\alpha_i > d$, among all the brackets in~\eqref{eq:equalityX_Xt}, the term $e^{\alpha_2t}$ can occur only from $(X_2(t) + 1)^d$ and $(\widetilde{X}_2(t) + 1)^d$.
    The coefficient in from of it will be equal to $d X_2(0)$ and $d \widetilde{X}_2(0)$, respectively.
    Due to the linear independence of the exponential functions with different growth rates these coefficients must be equal, so $X_2(0) = \widetilde{X}_2(0)$ as desired.

    \emph{Case $D > 1$.}
    By~\eqref{eq:analytic_solution}, the analytic continuation of $F(t)$ is a multivariate function with the branching points exactly at $-\frac{X_2(0)^{1 - D}}{\alpha_2 (1 - D)}, \ldots, -\frac{X_n(0)^{1 - D}}{\alpha_n (1 - D)}$, and, by the choice of $U$, these points are distinct.
    Therefore, $-\frac{\widetilde{X}_2(0)^{1 - D}}{\alpha_2 (1 - D)}, \ldots, -\frac{\widetilde{X}_n(0)^{1 - D}}{\alpha_n (1 - D)}$ must be a permutation of this set of points.
    Thus, these exists a unique $2 \leqslant j \leqslant n$ such that $C:= -\frac{X_2(0)^{1 - D}}{\alpha_2(1 - D)} = -\frac{\widetilde{X}_j(0)^{1 - D}}{\alpha_j (1 - D)}$.
    Then the principal (i.e., terms with negative degrees) part of the Puiseux expansion of $F(t)$ at $t = C$ will be equal to $(X_2(t) + 1)^d - 1$ on one hand and to $(\widetilde{X}_j(t) + 1)^d - 1$ on the other.
    This implies
    \[
    (X_2(t) + 1)^d = (\widetilde{X}_j(t) + 1)^d \implies X_2(t) = \omega \widetilde{X}_j(t) + (1 - \omega)
    \]
    for some $d$-th root of unity $\omega$.
    Since $\omega \widetilde{X}_j(t) + (1 - \omega)$ can be a solution of $x' = \alpha_2 x_j^D$ only for $\omega = 1$ and $j = 2$, we conclude that $X_2(t) = \widetilde{X}_2(t)$.
\end{proof}

\begin{proof}[Proof of Lemma~\ref{lem:distinct}]
    While we allow arbitrary $\KK$ of zero characteristic, the polynomial system is in fact defined over $\mathbb{Q}(x_1, \ldots, x_1^{(i - 1)}, x_1^{(i + 1)}, \ldots, x_1^{(n)})$, and the solutions will belong to the algebraic closure of this field.
    Therefore, proving the lemma for any fixed field $\KK$ would prove it for all fields, and we will choose $\KK = \mathbb{C}$.

    Combining Lemmas~\ref{lem:identifiability_to_algebra} and~\ref{lem:identifiability}, we conclude that that there exist $q_2, \ldots, q_n, r_2, \ldots, r_n \in \mathbb{C}[x_1^{(\leqslant n)}]$ such that none of $q_2, \ldots, q_n$ belongs to $I_{\balpha}$ and $q_i x_i - r_i \in I_{\balpha}$ for every $2 \leqslant i \leqslant n$.

    Consider any $0 \leqslant \ell \leqslant n - 1$.
    Let $\tuple{a, \hat{x}_2, \ldots, \hat{x}_n}$ and $\tuple{a, \tilde{x}_2, \ldots, \tilde{x}_n}$ be two distinct solutions of $p_{\balpha, 1} = \cdots = p_{\balpha, n} = 0$ as polynomials in $x_1^{(\ell)}, x_2, \ldots, x_n$ over $\overline{F_\ell}$ with coinciding $x_1^{(\ell)}$-coordinate.
    Since the solutions are distinct, there exists  $2 \leqslant j \leqslant n$ with $\hat{x}_j \neq \tilde{x}_j$.
    Let us prove that $b \neq 0$. Assume for the contradiction that $b := q_j|_{x_1^{(\ell)} = a} = 0$.
    Then $q_j$ and $f_{\min}$ of $I_{\balpha}$ have a common root as polynomials in $F_\ell[x_1^{(\ell)}]$.
    Since $f_{\min}$ is irreducible, it would imply that $q_j$ is divisible by $f_{\min}$ which is impossible due to $q_j \not\in I_{\balpha}$.
    Therefore, plugging our two solutions in $q_j x_j + r_j$ and using the fact that $\ideal{p_{\balpha, 1}, \ldots, p_{\balpha, n}} = I_{\balpha} \cap \mathbb{C}[x_1^{(\leqslant n)}, x_2, \ldots, x_n]$ (Lemma~\ref{lem:ideal_is_wanted}), we have
    \[
    0 = b \hat{x}_j + r_j|_{x_1^{(\ell)} = a} = b\tilde{x}_j + r_j|_{x_1^{(\ell)} = a}.
    \]
    Together with $b \neq 0$, this implies $\hat{x}_j = \tilde{x}_j$ leading to a contradiction with the existence of distinct solutions with the same $x_1^{(\ell)}$-coordinate.
\end{proof}

We can now combine the established properties of $\bx' = \bg_{\balpha}(\bx)$ from~\eqref{eq:sigma} for proving the sharpness of our bound.

\begin{proof}[Proof of Theorem~\ref{thm:sharp}]
   Let $U$ be the Zariski open set from Lemma~\ref{lem:sharp:count}.
   Since prime numbers are Zariski dense, we can choose $\balpha \in \mathbb{Q}^{n - 1}$ such that $\balpha \in U$ and the coordinates of $\balpha$ are prime numbers greater than $d$.
   We will prove that the bound from Theorem~\ref{theorem_general_specialized} is achieved on $\bx' = \bg_{\balpha}(\bx)$.

    Consider $f_{\min}$ for the elimination ideal $I_{\alpha} \cap \mathbb{K}[x_1^{(\infty)}]$.
    By Lemma~\ref{lem:ideal_is_wanted}, $f_{\min}$ belongs to the ideal generated by $p_{\balpha, 1}, \ldots, p_{\balpha, n}$.
    Fix any $0 \leqslant \ell \leqslant n$.
    If we consider $f_{\min}$ as a polynomial in $F_{\ell}[x_1^{(\ell)}]$ (see~\eqref{eq:field}), then it must vanish on the roots of the system $p_{\balpha, 1} = \cdots = p_{\balpha, n} = 0$ in $\overline{F}_\ell$.
    Therefore, its degree in $x_i^{(\ell)}$ must be greater or equal than the number of distinct $x_1^{(\ell)}$-coordinates of the solutions of the system.
    Lemmas~\ref{lem:sharp:count} and~\ref{lem:distinct} imply that this number is equal to $N_\ell$.
    Thus, $\deg_{x_1^{(\ell)}} f_{\min} \geqslant N_\ell$.
    On the other hand, Theorem~\ref{theorem_general_specialized} implies that the only monomial of degree $N_\ell$ in $x_1^{(\ell)}$ which can appear in $f_{\min}$ is $(x_1^{(\ell)})^{N_\ell}$.
    Therefore, this monomial does appear with a nonzero coefficient.

    For $\varepsilon \in \KK$, we define $\bg_{\balpha, \varepsilon}$ as the result of applying a transformation $x_1 \to x_1 + \varepsilon$ to $\bg_{\balpha}$.
    Since this transformation is invertible, it maps the minimal polynomial of $\bg_{\balpha}$ to the minimal polynomial of $\bg_{\balpha, \varepsilon}$.
    That is, the latter is equal to $f_{\min, \varepsilon} := f_{\min}(x_1 + \varepsilon, x_1', \ldots, x_1^{(n)})$.
    We have proved that $f_{\min}$ contains a monomial $x_1^{N_0}$.
    Therefore, the constant term of $f_{\min, \varepsilon}$ considered as a polynomial in $x_1^{(\infty)}$ is a nonzero polynomial in $\varepsilon$.
    Thus, there exists $\varepsilon^\ast \in \KK$ such that $f_{\min, \varepsilon^\ast}$ has a nonzero constant term.
    So the Newton polytope of $f_{\min, \varepsilon^\ast}$ is exactly the simplex defined by~\eqref{eq:bound_1}.
    This already shows that the bound~\eqref{eq:bound_1} is sharp.

    In order to prove the generic sharpness as stated in Theorem~\ref{thm:sharp}, we will apply Proposition~\ref{prop:specific_to_generic}.
    We will take $\mathcal{P}_1$ (resp., $\mathcal{P}_2, \ldots, \mathcal{P}_n$) to be the simplex containing all the points with the sum of the coordinates not exceeding $d$ (resp., $D$).
    Then $V(\mathcal{P}_1)$ (resp., $\mathcal{P}_2, \ldots, \mathcal{P}_n$) will be equal to $V_d$ (resp., $V_D$) in the notation of Theorem~\ref{thm:sharp}.
    We also take $\bg^\circ = \bg_{\balpha, \varepsilon^\ast}$, and denote the Newton polytope of its minimal polynomial by $\mathcal{N}^\ast$.
    Then by Proposition~\ref{prop:specific_to_generic} there exists $U \subset V_d \times V_D^{n - 1}$ such that, for every $\bg \in U$, the Newton polytope $\mathcal{N}$ of the minimal polynomial for $x_1$ contains a shift of $\mathcal{N}^\ast$.
    On the other hand, by Theorem~\ref{theorem_general_specialized}, we have $\mathcal{N} \subset \mathcal{N}^\ast$, so $\mathcal{N} = \mathcal{N}^\ast$.
\end{proof}

