\subsection{Proof of Theorem~\ref{thm:2d}} \label{sec:planar_sharpness}

We state and prove the following auxiliary lemma in full generality but we will use it only in the planar case.

\begin{lemma} \label{lem03}
    Let $p_1, \ldots, p_n$ be polynomials of degrees $d_1, \ldots, d_n$ in $\mathbb{K}[\mathbf{x}, \mathbf{y}]$ where $\bx = \tuple{x_1, \ldots, x_{n - 1}}$ and $\by = \tuple{y_1, \ldots, y_k}$.
    Let $\overline{p}_i$ denote the homogeneous component of degree $d_i$ in $p_i$, and assume that  $\overline{p}_i \in \mathbb{K}[\mathbf{x}]$ for every $1 \leqslant i \leqslant n$.
    Suppose that the ideal $I = \ideal{p_1, \ldots, p_n} \cap \mathbb{K}[\mathbf{y}]$ is principal, that is,
    $I = \ideal{g}$,
    where $g = g(\mathbf{y})$ is a nonzero irreducible polynomial. Then 
    $$\Res_{\mathbf{x}}(p_1, \ldots, p_n) = c\cdot g^m, \text{ for some } c \in \mathbb{K}, m \in \mathbb{Z}_{> 0}.$$
    \end{lemma}
    \begin{proof}

    We homogenize $p_1, \ldots, p_n$ in $\mathbf{x}$ using an additional variable $z$ and obtain
    $p_1^h, \ldots, p_n^h$. 

    Consider $\beta = \tuple{\beta_1, \ldots, \beta_k} \in \overline{{\mathbb{K}}}^k$.
    By~\cite[Ch.3~Th.~2.3]{cox2005using} $\beta$ is a zero of $\Res_{\mathbf{x}, z}(p_1^h, \ldots, p_n^h)$ if and only if there exists $\alpha = [\alpha_1: \ldots: \alpha_n] \in \mathbb{P}^{n - 1}$ such that $(\alpha, \beta)$ is a common zero of $p_1^h, \ldots, p_n^h$.

    If $\alpha_n = 0$, then $[\alpha_1 : \ldots : \alpha_{n - 1}]$ is a common zero for $\overline{p}_1, \ldots, \overline{p}_n$.
    Since $\overline{p}_1, \ldots, \overline{p}_n$ do not depend on $\mathbf{y}$, $(\alpha, \gamma)$ is a common root of $p_1^h, \ldots, p_n^h$ for every $\gamma \in \overline{\mathbb{K}}^k$.
    Therefore, $\Res_{\mathbf{x}, z} (p_1^h, \ldots, p_n^h)$ is identically zero, so is $\Res_{\mathbf{x}}(p_1, \ldots, p_n)$.
    Thus, we can take $c = 0$ and $m = 1$.
    Therefore, for the rest of the proof we will assume that $\alpha_n \neq 0$.

    Since $\alpha_n \neq 0$, then $\tuple{\dfrac{\alpha_1}{\alpha_n}, \ldots, \dfrac{\alpha_{n-1}}{\alpha_n}, \beta}$ is a common zero of $p_1, \ldots, p_n$.
    Thus, $\beta$ belongs to the projection of the solution set of $p_1 = \cdots = p_n = 0$.
    Therefore, the zero set of $\Res_{\mathbf{x}}(p_1, \ldots, p_n)$ coincides with this projection.

    By the elimination theorem \cite[Ch.~3, §~2, Th.~2]{cox1997ideals}, the zero set of $I$ is the closure of the projection, so, by the Hilbert's Nullstellensatz, $g^{m_1} \in \ideal{\Res_{\mathbf{x}}(p_1, \ldots, p_n)}$ for some $m_1 \in \mathbb{Z}_{> 0}$. 
    Hence, there exists $q \in \mathbb{K}[\mathbf{y}]$ such that

    \[
    g^{m_1} = q \cdot \Res_{\mathbf{x}}(p_1, \ldots, p_n).
    \]
    Since the factorization of $g^{m_1}$ is unique up to multiplication of the factors by invertible constants and $g$ is a nonzero irreducible polynomial, then $q = \Tilde{c} \cdot g^{m_2}$ for some $\Tilde{c} \in \mathbb{K}\backslash \{0\}, m_2 \in \mathbb{Z}_{\geqslant 0}$, and thus for $ m = m_1 - m_2, \; c = \frac{1}{\Tilde{c}}$ we have

    \[
    \Res_{\mathbf{x}}(p_1, \ldots, p_n) = c \cdot g^{m}.\qedhere
    \]
    \end{proof}

\begin{lemma} \label{lem5}
For the following polynomials $\bg = \tuple{g_1, g_2}$ in $\mathbb{K}[x_1, x_2] = \mathbb{K}[\mathbf{x}]$ of degrees $d_1, d_2 > 0$
    \begin{equation*}
            g_1(x_1, x_2)  = x_1^{d_1} + x_2^{d_1},\quad \text{ and }\quad
            g_2(x_1, x_2)  = x_2^{d_2} + 1,
    \end{equation*}
 the minimal polynomial $f_{\min}$ of $I_{\bg} \cap \KK[x_1^{(\infty)}]$ contains monomials $x_1^{d_1(d_1+d_2-1)}$ and $(x_1'')^{d_1}$.  
If $d_1 > d_2$ then $f_{\min}$ also contains the monomial $x_1^{d_1(d_1-1)}(x'_1)^{d_1}$. 
\end{lemma}
\begin{proof}
    Let $p_1 := x_1' - g_1(x_1, x_2)$ and
    \[
      p_2 := \mathcal{L}_{\bg}^\ast (p_1) = x''_1  -  d_1( x_1^{d_1-1} x'_1 +  x_2^{d_1+d_2-1} +   x_2^{d_1 - 1}).
    \]
    We compute $\Res_{x_2}(p_1, p_2)$. 
    Since $p_1$, as a polynomial in the variable $x_2$, has the roots $\alpha_i$, $1 \leqslant i \leqslant d_1$, where $\alpha_i = \xi_i (x'_1 - x_1^{d_1})^{\frac{1}{d_1}}$, $\{1^{\frac{1}{d_1}} \} = \{\xi_1, \ldots, \xi_{d_1}\}$,  
      then, by the Poisson formula~\cite[p.~427]{gelfand1994discriminants}, we have  \begin{equation}\label{eq:poisson}
        \Res_{x_2}(p_1, p_2) = \prod_{i=1}^{d_1} p_2 (\alpha_i) = \prod_{i = 1}^{d_1}(x''_1 - d_1 b(\alpha_i)), \; \text{ where } b(t) := x_1^{d_1 - 1}x'_1 + t^{d_1 + d_2 -1} + t^{d_1 - 1}. 
    \end{equation}
    By expanding the brackets, we obtain
 \begin{equation}\label{eq:poisson_expanded}
            \Res_{x_2}(p_1, p_2) = (x''_1)^{d_1} + (-d_1)^{d_1}\prod_{i=1}^{d_1} b(\alpha_i) + x''_1 p(x_1, x'_1, x''_1),
    \end{equation} 
    for some polynomial $p \in \overline{\mathbb K(x_1, x'_1)}[x''_1]$ with $\deg_{x_1''} p < d_1 - 1$. 
    Thus, $\Res_{x_2}(p_1, p_2)$ contains the monomial $(x''_1)^{d_1}$.


    We define $\tilde{p}_i := p_i|_{x_1' = x_2'' = 0}$ for $i = 1, 2$.
    Since $p_1$ and $p_2$ are $x_2-$monic and $\deg_{x_2} \tilde{p}_i = \deg_{x_2} p_i$, we have
     \[
    \Res_{x_2}(\tilde{p}_1,\tilde{p}_2) = \Res_{x_2}(p_1, p_2)|_{x'_1= x''_1 = 0}.
    \]
    Then 
    \[
    \Res_{x_2}(\Tilde{p}_1,\Tilde{p}_2) = \prod_{i=1}^{d_1} (x_1^{d_1 + d_2 - 1} + x_1^{d_1 - 1}),
    \]
    and this polynomial reaches the highest degree only in the term $x_1^{d_1(d_1 + d_2 - 1)}$. Then $\Res_{x_2}(\Tilde{f}_1,\Tilde{f}_2)$ contains the monomial $x_1^{d_1(d_1 + d_2 - 1)}$, so $\Res_{x_2}(p_1,p_2)$ does.


    Assume $d_1 > d_2$ and denote $(x'_1 - x_1^{d_1})^{\frac{1}{d_1}}$ by $a$.
    Consider the ring $\mathbb{K}[x_1, x'_1, x''_1,]$ with respect to the grading $\wdeg x''_1 = 0$, $\wdeg x'_1 = d_1$, $\wdeg x_1 = 1$.
    Since $x_1' - x_1^{d_1}$ is homogeneous of degree $d_1$ with respect to this grading, we can extend the grading to the ring $\mathbb K [x_1, x'_1, x''_1, a]$ by setting $\wdeg a = 1$.
    Then the expression
    \[
    b(\alpha_i) = x_1^{d_1 - 1} x'_1 + \xi_i^{d_2 - 1} a^{d_1 + d_2 - 1} - \xi_i^{-1} a^{d_1 -1}
    \]
    reaches the highest degree only in the term $x_1^{d_1 - 1} x'_1$. 
    Therefore, $\prod\limits_{i=1}^{d_1} b(\alpha_i)$ contains the monomial $x_1^{d_1(d_1 + d_2 - 1)} (x'_1)^{d_1}$, so does $\Res_{x_2}(p_1, p_2)$ by~\eqref{eq:poisson_expanded}.

    Finally, we will prove that $\Res_{x_2}(p_1, p_2)$ is in fact the minimal polynomial of the elimination ideal.
    Since the ideal $I_{\bg} \cap \mathbb{K}[x_1, x'_1, x''_1] = \ideal{f_{\min}}$ is principal, then
    by Lemma~\ref{lem03} 
    \[
    \Res_{x_2}(p_1, p_2) = c\cdot (f_{\min})^m, \text{ for some } c \in \mathbb{K}, m \in \mathbb{Z}_{> 0}.
    \]
    Assume $m \neq 1$. 
    Together with the decomposition~\eqref{eq:poisson}, this implies that $p_2(\alpha_i) = p_2(\alpha_j)$ for some $i \neq j$, so 
    \[
    \xi_{k}^{-1} a^{d_1 - 1}(1 - \xi_{k}^{d_2} a^{d_2}) = \alpha_k^{d_1 - 1}(1 - \alpha_k^{d_2}) \text{ for } k = i,j
    \]
    and we obtain
    \[
    a^{d_2} = \dfrac{1 - \xi_{i} \xi_{j}^{-1}}{\xi_{i}(\xi_i^{d_2 - 1} - \xi_{j}^{d_2 - 1})}.
    \]
    Since $\xi_i$ and $\xi_j$ are distinct $d_1$-th roots of unity, then $\xi_{i}(\xi_i^{d_2 - 1} - \xi_{j}^{d_2 - 1}) \neq 0$, so $a^{d_2} \in \overline{\mathbb{K}}$. Since $a$ is transcendental over $\mathbb{K}$, we get a contradiction to $m \neq 1$. So $m = 1$ and $\Res_{x_2}(p_1, p_2) = f_{\min}$. 
 \end{proof}

