\begin{lemma} \label{lem6} 
For the following polynomials $\bg = \tuple{g_1, g_2}$ in $\mathbb{K}[x_1, x_2]$ of degrees $d_1 > d_2 > 0$
    \begin{equation*}
            g_1(x_1, x_2)  = x_2^{d_1} + x_1x_2^{d_1-1},\quad \text{ and }\quad
            g_2(x_1, x_2) = x_2^{d_2},
    \end{equation*}
 the minimal polynomial $f_{\min}$  of $I_{\bg} \cap \KK[x_1^{(\infty)}]$ contains the monomial $(x'_1)^{2d_1-1}$. 
\end{lemma}

\begin{proof}
   Let $p_1 := x_1' - g_1(x_1, x_2)$ and
    \[
      p_2 := \mathcal{L}_{\bg}^\ast (p_1) =  x''_1 - d_1 x_2^{d_1+ d_2 -1} - x'_1 x_2^{d_1-1} - (d_1-1) x_1 x_2^{d_1+d_2-2}.
    \]

    We define $\Tilde{p}_i := p_i|_{x_1 = 0}$ for $i = 1, 2$.
    Since $p_1$ and $p_2$ are $x_2-$monic and $\deg_{x_2} \Tilde{p}_i = \deg_{x_2} p_i$ for $i = 1,2$, so
     \[
    \Res_{x_2}(\Tilde{p}_1,\Tilde{p}_2) = \Res_{x_2}(p_1, p_2)|_{x_1 = 0}.
    \]
    Since $\Tilde{p}_1$, as a polynomial in the variable $x_2$, has the roots $\alpha_i = \xi_i (x'_1)^{\frac{1}{d_1}}$, $1 \leqslant i \leqslant d_1$, where $\{1^{\frac{1}{d_1}} \} = \{\xi_1, \ldots, \xi_{d_1}\}$, then, by the Poisson formula~\cite[p.~427]{gelfand1994discriminants}, we have
    \[
        \Res_{x_2}(\Tilde{p}_1,\Tilde{p}_2) = \prod_{i=1}^{d_1} \Tilde{p}_2 (\alpha_i) = \prod_{i=1}^{d_1} \bigl(x''_1 - d_1\xi_i^{d_2 - 1} (x'_1)^{\frac{d_1 + d_2 - 1}{d_1}} - \xi_i^{- 1} (x'_1)^{\frac{2 d_1 - 1}{d_1}} \bigr).
    \]
    Since $d_1 > d_2$, then $\Res_{x_2}(\Tilde{p}_1,\Tilde{p}_2)$, as a polynomial in $\overline{\mathbb{K}(x''_1)}[(x'_1)^{\frac{1}{d_1}}]$, reaches the highest degree only in the term $(x'_1)^{2 d_1 - 1}$. Therefore, $\Res_{x_2}(\Tilde{p}_1,\Tilde{p}_2)$ contains the monomial $(x'_1)^{2 d_1 - 1}$, so $\Res_{x_2}(p_1, p_2)$ does.

    Now we will prove that $\Res_{x_2}(p_1, p_2)$ is in fact the minimal polynomial of the elimination ideal.
    Since the ideal $I_{\bg} \cap \mathbb{K}[x_1, x'_1, x''_1] = \ideal{f_{\min}}$ is principal, then
    by Lemma~\ref{lem03} 
    \[
    \Res_{x_2}(p_1, p_2) = c\cdot (f_{\min})^m, \text{ for some } c \in \mathbb{K}, m \in \mathbb{Z}_{> 0}.
    \]
    Assume $m \neq 1$, denote $(x'_1)^{\frac{1}{d_1}}$ by $a$ and replace the variable $x_1$ by $0$. 
    Then $\Tilde{p}_2(\alpha_i) = \Tilde{p}_2(\alpha_j)$ for some $i,j$
    \[
    x''_1 - d_1\xi_i^{d_2 - 1} a^{d_2} - \xi_i^{- 1} a^{d_1} = x''_1 -d_1\xi_j^{d_2 - 1} a^{d_2} - \xi_j^{- 1} a^{d_1}
    \]
    and we obtain
    \[
    a^{d_1 - d_2} = \dfrac{d_1(\xi_i^{d_2 - 1} - \xi_j^{d_2 - 1})}{\xi_j^{-1} - \xi_i^{-1}}.
    \]
    Since $\xi_i$ and $\xi_j$ are distinct $d_1$th roots of unity, then $\xi_j^{-1} - \xi_i^{-1} \neq 0$, so $a^{d_1 - d_2} \in \overline{\mathbb{K}}$.
    Since $a$ is transcendental, we get a contradiction to $m \neq 1$. So $m = 1$ and $\Res_{x_2}(p_2, p_1) = f_{\min}$.
\end{proof}

\begin{proof}[Proof of Theorem~\ref{thm:2d}]
The case $d_1 \leqslant d_2$ follows from Theorem~\ref{thm:sharp}.
Thus, in the rest of the proof we focus on the case $d_1 > d_2$.
In this case, the desired Newton polytope is a pyramid with the vertices corresponding to the monomials $1$, $x_1^{d_1(d_1 + d_2 - 1)}$, $(x_1')^{2d_1 - 1}$, $(x_1'')^{d_1}$, and~$x_1^{d_1(d_1 - 1)}( x_1')^{d_1}$ (see Figure~\ref{fig:2d}).

Consider the system $\bx' = \bg^\ast(\bx)$ from Lemma~\ref{lem5}.
The minimal polynomial $f_{\min}^\ast$ in this case contains monomials $x_1^{d_1(d_1 + d_2 - 1)}$, $(x_1')^{2d_1 - 1}$ and $(x_1'')^{d_1}$.
For $\varepsilon \in \KK$, we define $\bg^\ast_\varepsilon$ as the result of applying a transformation $x_1 \to x_1 + \varepsilon$ to $\bg^\ast$.
Since this transformation is invertible, it maps the minimal polynomial of $\bg^\ast$ to the minimal polynomial of $\bg^\ast_{\varepsilon}$.
That is, the latter is equal to $f_{\min, \varepsilon}^\ast := f_{\min}^\ast(x_1 + \varepsilon, x_1', x_1'')$.
We have proved that since $f_{\min}^\ast$ contains a monomial $x_1^{d_1(d_1 + d_2 - 1)}$.
Therefore, the constant term of $f_{\min, \varepsilon}^\ast$ considered as a polynomial in $x_1, x_1', x_1''$ is a nonzero polynomial in $\varepsilon$.
Thus, there exists $\varepsilon^\ast \in \KK$ such that $f_{\min, \varepsilon^\ast}^\ast$ has a nonzero constant term.

We apply Proposition~\ref{prop:specific_to_generic} twice: to $\bg^\ast_{\varepsilon^\ast}$ constructed above and to $\bg^{**}$ from Lemma~\ref{lem6}.
We denote the resulting Zariski open sets $U_1, U_2 \supset V_{2, d_1} \times V_{2, d_2}$.
Consider an element $\bg \in U_1\cap U_2$.
Then the Newton polytope of $\bg$ contains nonegative shifts $x_1^{d_1(d_1 + d_2 - 1)}$, $(x_1')^{2d_1 - 1}$, $(x_1'')^{d_1}$, and~$x_1^{d_1(d_1 - 1)}( x_1')^{d_1}$.
Since these monomials are vertices of the upper bound given by Theorem~\ref{theorem_general_specialized}, the only possible shift is the zero shift, so $f_{\min}$ for $\bg$ contains these monomials.
Since the shift of the Newton polygon of $f_{\min, \varepsilon}^\ast$ is zero, $f_{\min}$ also contains~$1$.
\end{proof}

