\section{Algorithm}\label{sec:algorithm}
In this section we will use the bound from Theorem~\ref{theorem_general_specialized} to compute the minimal differential equation in $x_1$ for a system of differential equations of the form
\begin{equation} \label{eq::ODE}
    \bx' = \bg(\bx),
\end{equation}
where $\bx = \tuple{x_1, \ldots, x_n}$ and $\bg \in \KK[\bx]^n$. 

We begin with the first version of the algorithm which is randomized and, thus, may produce an incorrect result (for the probability analysis, see Proposition~\ref{prop:prob}).

\begin{algorithm}[H]
 \caption{(Randomized) computation of the minimal polynomial}
 \label{alg:fmin}
 \begin{algorithmic}[1]
    \Require  An ODE system
    \[
     \bx' = \bg(\bx),
    \]
    where $\bx = \tuple{x_1, \ldots, x_n}$ and $\bg \in \mathbb{Q}[\bx^{(\infty)}]$, an integer $R > 0$ (randomization parameter).
    \Ensure a polynomial $f \in \mathbb{Q}[x_1^{(\infty)}]$ for which one of the following holds
    \begin{itemize}
        \item $f$ is the minimal polynomial of $\ideal{ \bx' - \bg(\bx)}^{(\infty)} \cap \mathbb{Q}[x_1^{(\infty)}]$ (see~\eqref{id}) 
        \item or $f$ does not belong to $\ideal{\bx' - \bg(\bx)}^{(\infty)}$.
    \end{itemize}

    \State \label{line:order} $\nu \gets \operatorname{rank}(\frac{\partial}{\partial x_j}\mathcal{L}_{\bg}^{i - 1}(x_1))_{i, j = 1}^n$

    \State Compute $S := \{s_1, \ldots, s_{\ell} \} \subset \mathbb{Q}[x_1^{(\infty)}]$ such that $\supp f_{\min} \subset S $ using  Theorem~\ref{theorem_general} and $\nu$


    \State $h_i\gets \mathcal{R}_{\bg}(s_i)$ (see Notation~\ref{not:proofs_notation}) for $i=1,\dots, \ell$.

    \State \label{line:points}Choose $\ell$ points $p_1, \ldots, p_\ell \in \mathbb{Z}^n$ by sampling uniformly at random from $[-R, R] \cap \mathbb{Z}$.

    \State \label{line:matrix}$M\gets (h_i(p_j))_{1\leqslant i,j \leqslant \ell}$ 
    \State $\mathcal{C} \leftarrow $ a basis of $\ker(M)$ 

    \State $F = \gcd \bigl(\{ \sum_{i=1}^{\ell}c_is_i \; | \; \mathbf{c} \in \mathcal{C} \} \bigr)$
   \Return $F$
 \end{algorithmic}
\end{algorithm}


\begin{proposition}
  \label{prop:prob}
    Algorithm~\ref{alg:fmin} terminates and correct.
    Furthermore, for any $\mathbf{g} \in \mathbb{Q}[\mathbf{x}]^n$ there is a proper Zariski closed subset $Z \subset \mathbb{Q}^{n\ell}$ such that, for all choices $\tuple{p_1, \ldots, p_{\ell}} \in \mathbb{Q}^{n \ell} \setminus Z$ in line \ref{line:points}, the output of Algorithm ~\ref{alg:fmin} is equal to the minimal polynomial of $\ideal{\bx' - \bg(\bx)}^{(\infty)} \cap \mathbb{Q}[x_1^{(\infty)}]$.
\end{proposition}

\begin{lemma}
\label{lem::minors}
    Let $p_1,\dots,p_s \in \KK[\mathbf{x}]$ and denote by $V$ the vector space over $\KK$ spanned by the $p_i$'s. 
    Let $r:=\dim V\geqslant 1$ and introduce
    $s$ copies of $\mathbf{x}$, denoted $\mathbf{x}_1,\dots,\mathbf{x}_s$. 
    Let $N:=(p_i(\mathbf{x}_j))_{1\leqslant i,j \leqslant s}$. Then there exists a nonzero $r \times r$-minor of $N$.

\end{lemma}

\begin{proof}
   We will show this via induction on $r$. W.l.o.g. assume that $p_1,\dots,p_r$ form a basis of $V$. 
   For the base case let us notice that $p_1\not \equiv 0$. 
   For the induction step we now show that the $r\times r$-minor $N_r$ of $N$ consisting of the first $r$ rows and columns is nonzero.
   Laplace expansion around the first row yields
   \[
   N_r = \sum_{i=1}^r (-1)^{i + 1} p_i(\mathbf{x}_1) N_{i,r-1}
   \]
   with $N_{i,r-1}$ is the minor of $N$ with
   rows indexed by $\mathbf{x}_2,\dots,\mathbf{x}_r$ and columns indexed
   by $p_1,\dots,p_{i-1},p_{i+1},\dots,p_r$. By the induction hypothesis
   at least one of the $N_{i,r-1}$ is nonzero. Then, since all the $N_{i,r-1}$
   include only the variables in $\mathbf{x}_2,\dots,\mathbf{x}_r$, $N_r = 0$ implies that there is a nontrivial $\KK$-linear relation between $p_1,\dots,p_r$, a contradiction.
\end{proof}


\begin{proof}[Proof of Proposition~\ref{prop:prob}]
  The termination of the algorithm is clear.

  To prove the correctness of the algorithm, we will use the notation
  of Algorithm \ref{alg:fmin} throughout the proof. 
  First we prove that the order of $f_{\min}$ is equal to $\nu$. 
  Lemma~\ref{lem::substitution} implies that the order of $f_{\min}$ equals to the transcendence degree of $\mathcal{R}_{\bg}(x_1^{(0)}),\dots,\mathcal{R}_{\bg}(x_1^{(n)})$ over $\mathbb{Q}$.
  By~\cite[Proposition 2.4]{ehrenborg1993apolarity} this transcendence degree is equal to the rank of the Jacobian of these polynomials.
  Since $\mathcal{R}_{\bg}(x_1^{(i)}) = \mathcal{L}_{\bg}^{i}(x_1)$ for every $i \geqslant 0$, this rank is equal to the one computed on line~\ref{line:order}.   

  Now we prove the correctness of the remaining part of the algorithm. Denote by
  $\mathbb{K}\langle S \rangle$ the $\mathbb{K}$-linear span of $S$. For any
  $f:= \sum\limits_{s\in S}\alpha_ss \in \mathbb{K}\langle S\rangle $ note that, Lemma
  \ref{lem::substitution} implies
  \[
  f\in I\; \Leftrightarrow \;\mathcal{R}_{\bg}(f) = 0 \; \Leftrightarrow \sum_{s\in S}\alpha_s\mathcal{R}_{\bg}(s) = 0\; \Leftrightarrow \; \sum_{i=1}^{\ell}\alpha_{s_i}h_i = 0. 
  \]
  Then, if we introduce $\ell$ duplicates of the
  variables $\bx$, denoted $\mathbf{x}_i$ for
  $i= 1,\ldots,\ell$, then the elements in
  $I\cap \mathbb{K}\langle S\rangle$ correspond to the kernel (in
  $\mathbb{K}^n$) of the matrix $N(\bx_1, \ldots, \bx_\ell):=(h_i(\mathbf{x}_j))_{1\leqslant i,j\leqslant \ell}$.
   Using this notation, matrix $M$ in Algorithm \ref{alg:fmin} can be written as $N(p_1, \ldots, p_\ell) =  \bigl( h_i(p_j) \bigr)_{1\leqslant i, j \leqslant \ell}$. 
  Hence $\operatorname{ker}(N)\subset \operatorname{ker}(M)$ with
  equality if and only if
  $r:=\operatorname{rk}(N) = \operatorname{rk}(M)$.



  Let $Z$ be the Zariski closed subset of
  $\mathbb{Q}^{n\ell}$ defined by the vanishing of the $r\times r$-minors of
  $N(\bx_1, \ldots, \bx_\ell)$. 
  By Lemma~\ref{lem::minors}, $Z$ is a proper Zariski closed subset of $\mathbb{Q}^{n\ell}$.  Then choosing  $\tuple{p_1,\dots,p_\ell}$ outside $Z$ will ensure the equality $\rk(N) = \rk(M)$.

  If this is the case, then the elements in the kernel of $M$ correspond
  to the elements in $I\cap \mathbb{K}\langle S\rangle$ and by applying Theorem~\ref{theorem_general_specialized} this kernel is nonempty and contains the minimal polynomial. 
  Then the gcd of a basis of this
  vector space gives the desired minimal polynomial.

  Finally, if we choose $\tuple{p_1, \ldots, p_{\ell}} \in Z$, then $\operatorname{ker}(N)\subsetneq \operatorname{ker}(M)$ and there exists an element in the kernel of $M$ that does not correspond to an element in the ideal $I \cap \mathbb{K}\langle S\rangle$. Then the gcd of a basis of $\operatorname{ker}(M)$ gives a polynomial that does not belong to the differential ideal $\ideal{\bx' - \bg(\bx)}^{(\infty)} \cap \mathbb{Q}[x_1^{(\infty)}]$.
\end{proof}


\begin{lemma} \label{lem::error}
    For fixed $\mathbf{g} \in \mathbb{Q}[\mathbf{x}]^n$ the Algorithm~\ref{alg:fmin} computes a wrong result with probability at most $\mathcal{O}(\frac{1}{R})$ as $R \to \infty$.
\end{lemma}

\begin{proof}
    By Proposition~\ref{prop:prob} there exists a proper Zariski closed subset $Z$ of $\mathbb{Q}^{n\ell}$ s.t. only by choosing $\tuple{p_1, \ldots, p_{\ell}} \in Z$ with $p_i\in \mathbb{Q}^n$ in line \ref{line:points} the output of the Algorithm~\ref{alg:fmin} may be wrong.
    Choose any nonzero polynomial $P$ vanishing on $Z$, let $D := \deg P$.
    By the Demillo-Lipton-Schwartz-Zippel lemma \cite[Proposition 98]{zippel_effective_1993} the probability of $P$ being zero on a point in $\mathbb{Q}^{n\ell}$ with entries sampled uniformly at random from $[-R, R] \cap \mathbb{Z}$ for some integer $R$ does not exceed $\frac{D}{2R}$.
\end{proof}

Combining Algorithm~\ref{alg:fmin} with a membership check provided by Lemma~\ref{lem::substitution}, we can produce the following complete algorithm.

\begin{algorithm}[H]
 \caption{(Guaranteed) computation of the minimal polynomial}
 \label{alg:check}
 \begin{algorithmic}[1]
     \Require An ODE system
    \[
     \bx' = \bg(\bx),
    \]
    where $\bx = \tuple{x_1, \ldots, x_n}$ and $\bg \in \mathbb{Q}[\bx^{(\infty)}]$
    \Ensure A minimal polynomial $f_{\min}$ of $\ideal{\bx' - \bg(\bx)}^{(\infty)} \cap \mathbb{Q}[x_1^{(\infty)}]$ (see~\eqref{id})
    \State $R \gets 1893$
    \While{true}    
        \State Apply Algorithm~\ref{alg:fmin} to $\bx' = \bg(\bx)$ and $R$, denote the result by $F$
        \State $A \gets \mathcal{R}_{\bg}(F)$
        \If{$A = 0$}
        \Return $f_{\min} = F$
        \Else
        \State Set $R \gets 2R$
        \EndIf
    \EndWhile

\end{algorithmic}
\end{algorithm}

\begin{proposition}
    Algorithm~\ref{alg:check} is correct and terminates with probability one.
\end{proposition}

\begin{proof}
    The correctness of the algorithm follows from Proposition~\ref{prop:prob} and Lemma~\ref{lem::substitution}.
    By Lemma~\ref{lem::error}, there exists a positive real number $C$ such that the probability of the algorithm not terminating at the $i$-th iteration of the while loop is at most $\frac{C}{2^{i - 1}R}$, where $R = 1893$.
    Then the probability of the algorithm terminating is at least
    \[
    1 - \frac{C}{2 R} \cdot \frac{C}{4 R} \cdot \frac{C}{8 R} \cdot \ldots = 1.\qedhere
    \]
\end{proof}



\begin{remark} \label{remark::algorithm}
    In practice instead of computing the kernel of matrix $M$ in line \ref{line:matrix} of Algorithm~\ref{alg:fmin} over $\mathbb{Q}$ directly, we may use multi-modular arithmetic.
    We compute $M$ modulo several primes.
    Then the kernel is computed for each prime and the results are combined using  the Chinese Remainder Theorem and rational reconstruction to obtain
    the kernel over $\mathbb{Q}$, see for example \cite{rus_result}. 
    To be more efficient, we shrink the support bound after the first prime and then actually work with the exact support.
\end{remark}

