\section{An idealised attribution test}\label{sec:idealtest}

In this section, building on (theoretical) results from the distribution testing literature, we present and analyze an algorithm \ to decide whether a distribution $\undertest$ is close to $\ideal$(both defined over the finite domain $\domain$) where we have access to a set of samples from $\undertest$. Furthermore, we have both \samp and \eval oracle access to the reference distribution \ideal. 

\Cref{alg:maintest} takes as input a set of samples $\cS = \{x_1, x_2, \ldots, x_n\}$ from $\undertest$, and oracle access to a distribution $\ideal$, outputs \accept if $\|\undertest - \ideal\|_1 \leq \eps_1$, and \reject if $\|\undertest - \ideal\|_1 \geq \varepsilon_2$. The pseudocode is presented in \cref{alg:maintest}; we outline the main ideas below.

The core idea of \cref{alg:maintest} involves \textit{bucketing}, where a ``bucket'' is a partition of the domain such that all the elements in a bucket have similar probabilities according to $\ideal$. (We will provide the formal definition shortly: for this discussion, it is enough to point out that the number of buckets in the partition is quite small, i.e., logarithmic in the support size, allowing for a sample-efficient tester.) 
The algorithm first draws a fresh set of samples $\cT$ from $\ideal$ and then counts the number of samples of $\cS$ and $\cT$ falling into each bucket. This is done using the $\bucketing$ algorithm (\cref{alg:bucket}).

Intuitively, if there is a big difference in the number of samples from $\cS$ falling into some bucket, as compared to the samples from $\cT$, then this is evidence that $\undertest$ and $\ideal$ differ. To make this rigorous, the algorithm then uses the $\dkw$ test (\cref{alg:DKW}) to determine whether the distribution of samples \emph{over buckets} induced by $\undertest$ and $\ideal$ are consistent.

At this stage, it could still be the case that the distributions induced over buckets are similar for both $\undertest$ and $\ideal$ even though the two distributions significantly differ, as all the discrepancy between the two distributions is hidden ``within the buckets''. To detect this, the
$\inbucket$ algorithm (\cref{alg:inbucket}) is then invoked to test the closeness of the (conditional) distributions within each bucket, using a variant of a chi-squared test for each.

To summarize, the $\dkw$ algorithm tests the closeness of the empirical cumulative distribution functions (CDFs) of the buckets (``global test''), while the $\inbucket$ algorithm tests the closeness of the samples in the buckets (``local tests''). If both tests pass, the algorithm returns \accept; otherwise, it returns \reject.

\begin{algorithm}
    \caption{}%
    \label{alg:maintest}
\begin{algorithmic}[1]    
    \State \textbf{Input}: Set of samples $\cS = \{x_1, x_2, \dots, x_n\}$, and distribution $\ideal$
    \State \textbf{Output}: $\accept$ if $\cS$ is drawn from $\ideal$, else $\reject$ 
    \State  Draw $n$ samples from $\ideal$ and store them in $\cT$
    \State $\Thresh_1 \gets \frac{c_3\eps_2 + \ell\eps_1}{2\ell}$
    \State $\Delta^S \gets \bucketing(\cS, \ideal)$
    \State $\Delta^T \gets \bucketing(\cT, \ideal)$
    \If{$\dkw(\Delta^S, \Delta^T, \Thresh_1)$ returns \reject}
        \State \Return $\reject$
    \EndIf
    \For {$i \in [\ell]$} \Comment{$\Delta^S, \Delta^T$ are lists of size $\ell$}
        \State $\Thresh_2 \gets \left(c_4\eps_2 + 2\ell\eps_1\right)/{2\ell \ideal(\bucket_i)}$
        \If{$\inbucket(\bucket^S_i, \bucket^T_i, \Thresh_2, \cS \cup \cT)$ returns \reject}
            \State \Return $\reject$
        \EndIf
    \EndFor
    \State \Return $\accept$
\end{algorithmic}
\end{algorithm}

\paragraph{Bucketing}
We define the buckets in terms of the probabilities of $\ideal$. We fix the number of buckets by $\ell \eqdef \flr{\log_2 \frac{|\domain|}{c_1\eps_2}} + 1$, and define the buckets as follows, for $1\leq j\leq \ell$:
\begin{equation}
    \label{eq:bucket}
    \bucket_j \eqdef \setOfSuchThat{ x \in \domain }{ 2^{-j} < \ideal(x) \leq 2^{-j+1}}
\end{equation}

We keep the other elements in the ``leftover bucket'' $\bucket_0$, i.e., for all $x \in \bucket_0$, $\ideal(x) \leq \frac{c_1\eps_2}{|\domain|}$. 
%
The $\bucketing$ algorithm takes as input the distribution $\ideal$ and a set of samples $X$. The algorithm distributes the samples in $\cS$ and $\cT$ into buckets. $\bucketing$ uses the $\eval$ oracle to evaluate the probability of the samples of $X$ in $\ideal$. The bucketing is done based on the probabilities of the samples in $X$ as described in \cref{eq:bucket}. 


\begin{algorithm}\small
    \caption{$\bucketing(\ideal, X)$}
    \label{alg:bucket}
\begin{algorithmic}[1]    
    \State \textbf{Input}: Distribution $\ideal$, and sample set $X = \{x_1, x_2, \dots, x_n\}$
    \State \textbf{Output}: List of buckets
    \State Initialise buckets $\bucket_0, \bucket_1, \ldots, \bucket_\ell$
    \For{$x \in  X$}
    \State $j \gets \flr{\log_2(\eval(\ideal, x))} + 1$
    \State $\bucket_j \gets \bucket_j \cup \{x\}$
    \EndFor
    \State \Return $(\bucket_0, \bucket_1, \ldots, \bucket_\ell)$
\end{algorithmic}
\end{algorithm}


\paragraph{The global test (DKW)}
The $\dkw$ algorithm takes as input two list of buckets $(\bucket^S_0, \bucket^S_1, \ldots, \bucket^S_\ell)$ and $(\bucket^T_0, \bucket^T_1, \ldots, \bucket^T_\ell)$, and a threshold $\Thresh$. The algorithm computes the empirical CDF for the two sets of buckets and determines the maximum pointwise difference between the empirical CDFs. If the difference is greater than the threshold $\Thresh$, the algorithm returns \reject. Otherwise it returns \accept (\cref{alg:DKW}).

\paragraph{The Local Test} The $\inbucket$ algorithm takes as input two buckets $\bucket^S_i$ and $\bucket^T_i$, as well as threshold $\Thresh$. The algorithm computes a chi-square-type statistic for each sample in $\bucket^S_i$ and compares their sum, $Z$, to the threshold $\Thresh$. If the sum of $Z$ is less than the threshold $\Thresh$, the algorithm returns \accept. Otherwise it returns \reject (\cref{alg:inbucket}).

\begin{algorithm}[t]
    \caption{$\dkw(\Delta^S, \Delta^T, \Thresh)$}
    \label{alg:DKW}
    \begin{algorithmic}[1]
    \State \textbf{Input}:
    Set of buckets $\Delta^S = (\bucket^S_0, \ldots, \bucket^S_{\ell}), \Delta^T = (\bucket^T_0, \ldots, \bucket^T_\ell)$, threshold $\Thresh$
    \State \textbf{Output}:  \accept or \reject 

    \State Set $m \gets |\bigcup_{i=1}^\ell \bucket^S_i|$
    \State Compute the empirical CDF for the two sets of buckets:
    $
       %
       \hat{\Delta}^S(i) = \frac{1}{m}\sum_{j=1}^{i} |\bucket^S_j|,
    \ \ 
        \hat{\Delta}^T(i) = \frac{1}{m}\sum_{j=1}^{i} |\bucket^T_j| 
    $
    \State \textbf{if} \ $  \max_i |\hat{\Delta}^S(i) - \hat{\Delta}^T(i)| > \Thresh$ \ \textbf{then} \ \Return \reject, \ \textbf{else} \ \Return \accept

    %
    %
    %
    %
    %
    \end{algorithmic}
\end{algorithm}


\begin{algorithm}[t]
    \caption{$\inbucket(\bucket^S_i, \bucket^T_i, \Thresh, X)$}
    \label{alg:inbucket}
    \begin{algorithmic}[1]
    \State \textbf{Input}: 
    Buckets $\bucket^S_i$, $\bucket^T_i$, Threshold $\Thresh$, Sample set $X$
    \State \textbf{Output}: \accept or \reject 
    \State $Z \gets 0$
    \For{$x \in X$} 
        \State $z_1 \gets \cnt(x, \bucket^S_i)$, \  $z_2 \gets \cnt(x, \bucket^T_i)$  \Comment{Computing multiplicity of $x$ in $\bucket^S_i, \bucket^T_i$}
        \State $Z \gets Z + \frac{(z_1 - z_2)^2 - z_1 - z_2}{\max(z_1+z_2, 1)}$
    \EndFor
    \State \textbf{if} \ $Z \geq \Thresh$ \ \textbf{then} \ \Return \reject, \ \textbf{else} \ \Return \accept
    %
    %
    %
    %
    %
    \end{algorithmic}
\end{algorithm}


\begin{theorem}[Adapted from~{\cite{CanonneJKL22}}]
    \label{thm:main}
    Let $\ideal$ be a fully specified distribution such that $\|\ideal\|_2 \leq \sqrt{2/|\domain|}$ and $\undertest$ be an unknown distribution, both over the same domain $\domain$. Then there exists an positive absolute constant $c $ such that, for any $0 \leq \eps_2 \leq 1$ and $0 \leq \eps_1 \leq c \eps_2/\ell$, there is an Algorithm that uses 
    $
    \tOh(|\domain|\left({\eps_1}/{\eps_2^2}\right)^2 + |\domain|\left({\eps_1}/{\eps_2^2}\right) + {\sqrt{|\domain|}}/{\eps_2^2})
    $
    many samples to distinguish between $\|\undertest - \ideal\|_1 \leq \eps_1$ and $\|\undertest - \ideal\|_1 \geq \eps_2$ with probability at least 4/5.
\end{theorem}
