        \State \textbf{Input}: LLM $\cL$ (with tokenizer $\tok$, and token distribution $\cLtok$), text $s$, depth parameter $d\geq 1$
	\State \textbf{Output}: An estimate of $\cL(s)$
        \State $\sigma \gets \enc(s)$
        \State \Return $\evalplus(\cLtok, \tok, \sigma, d)$
    \end{algorithmic}
