\begin{algorithm}[ht]
	\caption{$\evalplus(\cLtok, \tok, \sigma, d)$}
	\label{alg:evalplus}
	\begin{algorithmic}[1]    
		\State \textbf{Input}: Token distribution $\cLtok$, tokenizer $\tok$, token string $\sigma$, depth parameter $d\geq 1$
		\State \textbf{Output}:  A lower bound on the value of $\cL(s)$
		%
		\If{$|\sigma| \leq d$}
		%
		%
		\State $Coll \gets \getcoll(\tok, \sigma, d)$, \ $prob \gets 0$
		\For {$\sigma' \in Coll$}
		\State $prob \gets prob + \eval(\cLtok, \sigma') $
		\EndFor
		\State  \Return $prob$
		\EndIf
		\State \Return $\sum_{i=1}^{d} (\evalplus(\cLtok, \tok, \sigma_1 \sigma_2 \ldots \sigma_{i}, i) 
		\, \cdot \evalplus(\cLtok, \tok, \sigma_{i+1} \sigma_{i+2} \ldots \sigma_n, d))$ 
	\end{algorithmic}
\end{algorithm}

