\section{Appendix}\label{sec:appendix}
\subsection{Details of the proof of~\cref{thm:main}}
%
We first restate the theorem:
\begin{theorem}[Adapted from~{\cite{CanonneJKL22}}]
    \label{thm:main:restated}
    Let $\ideal$ be a fully specified distribution such that $\|\ideal\|_2 \leq \sqrt{2/|\domain|}$ and $\undertest$ be an unknown distribution, both over the same domain $\domain$. Then there exists an positive absolute constant $c $ such that, for any $0 \leq \eps_2 \leq 1$ and $0 \leq \eps_1 \leq c \eps_2/\ell$, there is an Algorithm that uses $$\tOh\left(|\domain|\left(\frac{\eps_1}{\eps_2^2}\right)^2 + |\domain|\left(\frac{\eps_1}{\eps_2^2}\right) + \frac{\sqrt{|\domain|}}{\eps_2^2}\right)$$ many samples to distinguish between $\|\undertest - \ideal\|_1 \leq \eps_1$ and $\|\undertest - \ideal\|_1 \geq \eps_2$ with probability at least 4/5. (Moreover, a detailed bound can be found in \cref{eq:sample:n1:restated,eq:sample:n2:restated}.) 
\end{theorem}
The beginning of the proof is given in the submission; we reproduce it here for completeness, but the changes start at~\cref{eq:sample:n2:restated}.
\begin{proof}
Let us assume that the buckets $\bucket_0, \ldots, \bucket_\ell$ are defined as in \cref{eq:bucket}. By~\cite[Lemma~C.7]{CanonneJKL22}, if $\|{\undertest} - {\ideal}\|_1 \leq \eps_1$, then
\begin{enumerate}
    \item $\undertest(\bucket_0) - \ideal(\bucket_0) \leq \eps_1$ 
    \item $|\undertest(\bucket_j) - \ideal(\bucket_j)| \leq \eps_1$ for all $1\leq j\leq \ell$
    \item $\|\cond{\undertest}{\bucket_j}- \cond{\ideal}{\bucket_j}\|_1 \leq \frac{2\eps_1}{\ideal(\bucket_j)}$ for all $1\leq j\leq \ell$
\end{enumerate}

\noindent By~\cite[Lemma~C.8]{CanonneJKL22}, conversely, for any choice of constants $c_1,c_2,c_3,c_4 > 0$, if
\begin{enumerate}
    \item $\undertest(\bucket_0) \leq c_2\eps_2$ 
    \item $|\undertest(\bucket_j) - \ideal(\bucket_j)| \leq \frac{c_3\eps_2}{\ell}$ for all $1\leq j\leq \ell$
    \item $\|\cond{\undertest}{\bucket_j} - \cond{\ideal}{\bucket_j}\|_1 \leq \frac{c_4\eps_2}{\ell\cdot \ideal(\bucket_j)}$
\end{enumerate}
then $\|{\undertest} - {\ideal}\|_1 \leq (c_1 + c_2 + 2c_3 + c_4)\eps_2$.\medskip

This gives the following constraints on $c_1,c_2$ and (looking ahead) probabilities of failure $\delta_1, \delta_2$:
\begin{align}
    c_1 + c_2 + \frac{1}{2}c_3 + c_4 &\leq c \label{eq:c1:restated}\\
    \eps_1 &\leq (c_2 - c_1)\cdot \eps_2\\
    \eps_1 &\leq c_3\cdot \frac{\eps_2}{\ell} \label{eq:11}\\
    2\eps_1 &\leq c_4\cdot \frac{\eps_2}{\ell} \label{eq:12}\\
    \delta_1 + \ell \cdot \delta_2 &\leq \frac{1}{5} 
\end{align}
We will also add the condition 
\begin{align}
c_4 \geq 2c_3
\end{align}
on the constants, which will be used in the analysis (which uses $\frac{c_4\eps_2}{2\ell} \geq \frac{2c_3\eps_2}{\ell}$). Note that this condition, combined with~\eqref{eq:12}, implies~\eqref{eq:11}.
\begin{enumerate}
    \item For $\bucket_0$ we want to distinguish between $|\undertest(\bucket_0) - \ideal(\bucket_0)| \leq \eps_1$ from $|\undertest(\bucket_0) - \ideal(\bucket_0)| \geq (c_2 - c_1)\eps_2$. And for every subsequent buckets $1\leq j\leq \ell$, we need to distinguish $|\undertest(\bucket_j) - \ideal(\bucket_j)| \leq \eps_1$ from $|\undertest(\bucket_j)-\ideal(\bucket_j)| > \frac{c_3\eps_2}{\ell}$ with error probability $\delta_1$ (overall). This can be done by empirically estimating the distributions $\undertest(\bucket_j)$ and $\ideal(\bucket_j)$ (where $j = 0, 1, \ldots \ell$) within the bound $\pm \eta \eqdef \min\left(\frac{(c_2-c_1)\eps_2 - \eps_1}{4},\frac{c_3\eps_2-\ell\eps_1}{4\ell}\right)$.
    From \cref{lem:dkw}, this would require 
    \begin{equation}
        \label{eq:sample:n1:restated}
        n_1 = \clg{ \frac{8}{\eta^2} \ln \frac{4}{\delta_1} }
    \end{equation}
    samples from each of the distributions $\undertest$ and $\ideal$.

    \item For every $1\leq j\leq \ell$, we need to distinguish $\|\cond{\undertest}{\bucket_j}-\cond{\ideal}{\bucket_j}\|_1 \leq \frac{2\eps_1}{\ideal(\bucket_j)}$ from $\|\cond{\undertest}{\bucket_j}-\cond{\ideal}{\bucket_j}\|_1 > \frac{c_4\eps_2}{\ell\cdot \ideal(\bucket_j)}$ with error probability $\delta_2$ (each). To do so, we take 
    \begin{equation}
        \label{eq:sample:n2:restated}
            n_2 = \left\lceil C\cdot \left(|\domain|\max\!\left(\left(\tfrac{\eps_1}{\eps_2^2}\right)^2,\left(\tfrac{\eps_1}{\eps_2^2}\right)\right) + \tfrac{\sqrt{|\domain|}}{\eps_2^2}\right) \ln \ell  \right\rceil
    \end{equation}
    samples in total, where $C=C(c_1,c_2,c_3,c_4)$ is an absolute constant, and call the $\ell$ identity testing algorithms on each of the distributions, with the above parameter (for $\eps_2$) using for the $j$-th the samples which fell in $\bucket_j$. The details of the above bound follow the same outline as~\cite{CanonneJKL22}: we provide them here for completeness. 

    For any $1\leq j\leq \ell$ such that $\ideal(\bucket_j)\geq \frac{c_4\eps_2}{2\ell} \geq \frac{2c_3\eps_2}{\ell}$,\footnote{We only need to consider the $j$s such that $\ideal(\bucket_j)\geq \frac{c_4\eps_2}{2\ell}$, as for the others the condition $\|\cond{\undertest}{\bucket_j}-\cond{\ideal}{\bucket_j}\|_1 > \frac{c_4\eps_2}{\ell\cdot \ideal(\bucket_j)}$ can never be satisfied (the RHS being greater than 2) and so the test is trivial.} then we can assume that $\undertest(\bucket_j)\geq \frac{1}{2}\ideal(\bucket_j)$, otherwise
    \[
        |\undertest(\bucket_j) - \ideal(\bucket_j)| > \frac{1}{2}\ideal(\bucket_j) \geq \frac{c_3\eps_2}{\ell}
    \]
    and the test from 2) will reject anyway. Now, by a Chernoff bound, taking $n_2$ samples from $\undertest$ we will get at least
    \[
        n_{2,j} \coloneqq n_2\cdot \frac{\undertest(\bucket_j) }{2}
    \]
    samples from $\cond{\undertest}{\bucket_j}$ with probability at least $1-e^{-c_3\eps_2 n_2/\ell} \geq 1-\frac{\delta_2}{2}$, as long as 
    \[
    n_2 \geq \frac{\ell}{c_3\eps_2} \ln \frac{2}{\delta_2}
    \]
    (and we can use the same $n_2$ samples for all at most $\ell$ such intervals, by a union bound). We use these $n_{2,j}$ samples for the \textsf{Local} test on the $j$-th bucket, with parameters
    \[
        \eps_2' \eqdef \frac{c_4\eps_2}{\ell\ideal(\bucket_j)},\quad \eps_1'\eqdef \frac{2\eps_1}{\ideal({\bucket_j})}
    \]
    which is guaranteed to be accurate with probability $\delta_2/2$ as long as
    \[
        n_{2,j} \geq C\cdot \left(|\bucket_j|\left(\frac{{\eps'}_1}{{\eps'}_2^2}\right)^2 + |\bucket_j|\left(\frac{{\eps'}_1}{{\eps'}_2^2}\right) + \frac{\sqrt{|\bucket_j|}}{{\eps'}_2^2}\right) \ln\frac{2}{\delta_2}
    \]
    (from Theorem~2.1 of~\cite{CanonneJKL22:arxiv}). Since 
    $
    \ideal({\bucket_j})  \leq 1
    $
    and $|\bucket_j| \leq |\domain|$, the condition from above, which from the settings of $\eps_1', \eps_2'$ can be rewritten as
    \begin{align*}
    %
        n_{2,j} \geq C\cdot \left(|\bucket_j|\cdot \frac{4\ell^2\ideal({\bucket_j})^2}{c_4^2} \cdot \left(\frac{{\eps}_1}{{\eps}_2^2}\right)^2 + |\bucket_j|\cdot \frac{2\ell\ideal({\bucket_j})}{c_4} \cdot \left(\frac{{\eps'}_1}{{\eps'}_2^2}\right)\right . \\ 
        \left . + \frac{\sqrt{|\bucket_j|}}{{\eps'}_2^2}\cdot \frac{\ell^2\ideal({\bucket_j})^2}{c_4^2} \cdot \right) \ln\frac{2}{\delta_2}
    %
    \end{align*}
    gives the (stronger, sufficient) condition,
    \[
        n_{2,j} \geq C\cdot \frac{\ideal(\bucket_j)}{4}\cdot  \left(\frac{16\ell^2}{c_4^2} \cdot |\domain| \cdot  \left(\frac{{\eps}_1}{{\eps}_2^2}\right)^2 + \frac{8\ell}{c_4}\cdot |\domain| \cdot \left(\frac{{\eps'}_1}{{\eps'}_2^2}\right) + \frac{4\ell^2}{c_4^2} \cdot \frac{\sqrt{|\domain|}}{{\eps'}_2^2}\right) \ln\frac{2}{\delta_2}\,. \tag{$\ast$}
    \]
    But as 
    \[
    n_{2,j} = n_2\cdot \frac{\undertest(\bucket_j) }{2} \geq n_2\cdot \frac{\ideal(\bucket_j) }{4}
    \]
    fo the buckets considered, the condition $(\ast)$ holds simultaneously for all these buckets with probability at least $1-\delta_2/2$, as long as (1)~$n_2 \geq \frac{\ell}{c_3\eps_2} \ln \frac{2}{\delta_2}$, and (2)~$n_2$ satisfies
    \[
        n_{2} \geq C\cdot \left(\frac{16\ell^2}{c_4^2} \cdot |\domain| \cdot  \left(\frac{{\eps}_1}{{\eps}_2^2}\right)^2 + \frac{8\ell}{c_4}\cdot |\domain| \cdot \left(\frac{{\eps'}_1}{{\eps'}_2^2}\right) + \frac{4\ell^2}{c_4^2} \cdot \frac{\sqrt{|\domain|}}{{\eps'}_2^2}\right) \ln\frac{2}{\delta_2}.
    \]
    That is, for this step to be successful with probability at least $1-\ell\cdot \delta$ overall by a union bound, it suffices to have
    \begin{align}
        n_{2} \geq \max\left(\frac{\ell}{c_3\eps_2} , C\cdot \left(\frac{16\ell^2}{c_4^2} \cdot |\domain| \cdot  \left(\frac{{\eps}_1}{{\eps}_2^2}\right)^2 + \frac{8\ell}{c_4}\cdot |\domain| \cdot \left(\frac{{\eps'}_1}{{\eps'}_2^2}\right) + \frac{4\ell^2}{c_4^2} \cdot \frac{\sqrt{|\domain|}}{{\eps'}_2^2}\right)\right) \ln\frac{2}{\delta_2}
    \end{align}
\end{enumerate}
\end{proof}
